30	/**
31	 * A {@link Request} that loads a {@link com.bumptech.glide.load.engine.Resource} into a given
32	 * {@link Target}.
33	 *
34	 * @param <R> The type of the resource that will be transcoded from the loaded resource.
35	 */
36	public final class SingleRequest<R> implements Request, SizeReadyCallback, ResourceCallback {
37	  /** Tag for logging internal events, not generally suitable for public use. */
38	  private static final String TAG = "GlideRequest";
39	
40	  /** Tag for logging externally useful events (request completion, timing etc). */
41	  private static final String GLIDE_TAG = "Glide";
42	
43	  private static final boolean IS_VERBOSE_LOGGABLE = Log.isLoggable(TAG, Log.VERBOSE);
44	  private int cookie;
