46	  private enum Status {
47	    /** Created but not yet running. */
48	    PENDING,
49	    /** In the process of fetching media. */
50	    RUNNING,
51	    /** Waiting for a callback given to the Target to be called to determine target dimensions. */
52	    WAITING_FOR_SIZE,
53	    /** Finished loading media successfully. */
54	    COMPLETE,
55	    /** Failed to load media, may be restarted. */
56	    FAILED,
57	    /** Cleared by the user with a placeholder set, may be restarted. */
58	    CLEARED,
59	  }
