174	  // We are in fact locking on the same lock that will be used for all subsequent method calls.
175	  @SuppressWarnings("GuardedBy")
176	  private SingleRequest(
177	      Context context,
178	      GlideContext glideContext,
179	      @NonNull Object requestLock,
180	      @Nullable Object model,
181	      Class<R> transcodeClass,
182	      BaseRequestOptions<?> requestOptions,
183	      int overrideWidth,
184	      int overrideHeight,
185	      Priority priority,
186	      Target<R> target,
187	      @Nullable RequestListener<R> targetListener,
188	      @Nullable List<RequestListener<R>> requestListeners,
189	      RequestCoordinator requestCoordinator,
190	      Engine engine,
191	      TransitionFactory<? super R> animationFactory,
192	      Executor callbackExecutor) {
193	    this.requestLock = requestLock;
194	    this.context = context;
195	    this.glideContext = glideContext;
196	    this.model = model;
197	    this.transcodeClass = transcodeClass;
198	    this.requestOptions = requestOptions;
199	    this.overrideWidth = overrideWidth;
200	    this.overrideHeight = overrideHeight;
201	    this.priority = priority;
202	    this.target = target;
203	    this.targetListener = targetListener;
204	    this.requestListeners = requestListeners;
205	    this.requestCoordinator = requestCoordinator;
206	    this.engine = engine;
207	    this.animationFactory = animationFactory;
208	    this.callbackExecutor = callbackExecutor;
209	    status = Status.PENDING;
210	
211	    if (requestOrigin == null && glideContext.getExperiments().isEnabled(LogRequestOrigins.class)) {
212	      requestOrigin = new RuntimeException("Glide request origin trace");
213	    }
214	  }
