216	  @Override
217	  public void begin() {
218	    synchronized (requestLock) {
219	      assertNotCallingCallbacks();
220	      stateVerifier.throwIfRecycled();
221	      startTime = LogTime.getLogTime();
222	      if (model == null) {
223	        if (Util.isValidDimensions(overrideWidth, overrideHeight)) {
224	          width = overrideWidth;
225	          height = overrideHeight;
226	        }
227	        // Only log at more verbose log levels if the user has set a fallback drawable, because
228	        // fallback Drawables indicate the user expects null models occasionally.
229	        int logLevel = getFallbackDrawable() == null ? Log.WARN : Log.DEBUG;
230	        onLoadFailed(new GlideException("Received null model"), logLevel);
231	        return;
232	      }
233	
234	      if (status == Status.RUNNING) {
235	        throw new IllegalArgumentException("Cannot restart a running request");
236	      }
237	
238	      // If we're restarted after we're complete (usually via something like a notifyDataSetChanged
239	      // that starts an identical request into the same Target or View), we can simply use the
240	      // resource and size we retrieved the last time around and skip obtaining a new size, starting
241	      // a new load etc. This does mean that users who want to restart a load because they expect
242	      // that the view size has changed will need to explicitly clear the View or Target before
243	      // starting the new load.
244	      if (status == Status.COMPLETE) {
245	        onResourceReady(
246	            resource, DataSource.MEMORY_CACHE, /* isLoadedFromAlternateCacheKey= */ false);
247	        return;
248	      }
249	
250	      // Restarts for requests that are neither complete nor running can be treated as new requests
251	      // and can run again from the beginning.
252	
253	      experimentalNotifyRequestStarted(model);
254	
255	      cookie = GlideTrace.beginSectionAsync(TAG);
256	      status = Status.WAITING_FOR_SIZE;
257	      if (Util.isValidDimensions(overrideWidth, overrideHeight)) {
258	        onSizeReady(overrideWidth, overrideHeight);
259	      } else {
260	        target.getSize(this);
261	      }
262	
263	      if ((status == Status.RUNNING || status == Status.WAITING_FOR_SIZE)
264	          && canNotifyStatusChanged()) {
265	        target.onLoadStarted(getPlaceholderDrawable());
266	      }
267	      if (IS_VERBOSE_LOGGABLE) {
268	        logV("finished run method in " + LogTime.getElapsedMillis(startTime));
269	      }
270	    }
271	  }
272	
273	  private void experimentalNotifyRequestStarted(Object model) {
274	    if (requestListeners == null) {
275	      return;
276	    }
277	    for (RequestListener<?> requestListener : requestListeners) {
278	      if (requestListener instanceof ExperimentalRequestListener) {
279	        ((ExperimentalRequestListener<?>) requestListener).onRequestStarted(model);
280	      }
281	    }
282	  }
