284	  /**
285	   * Cancels the current load but does not release any resources held by the request and continues
286	   * to display the loaded resource if the load completed before the call to cancel.
287	   *
288	   * <p>Cancelled requests can be restarted with a subsequent call to {@link #begin()}.
289	   *
290	   * @see #clear()
291	   */
292	  @GuardedBy("requestLock")
293	  private void cancel() {
294	    assertNotCallingCallbacks();
295	    stateVerifier.throwIfRecycled();
296	    target.removeCallback(this);
297	    if (loadStatus != null) {
298	      loadStatus.cancel();
299	      loadStatus = null;
300	    }
301	  }
302	
303	  // Avoids difficult to understand errors like #2413.
304	  @GuardedBy("requestLock")
305	  private void assertNotCallingCallbacks() {
306	    if (isCallingCallbacks) {
307	      throw new IllegalStateException(
308	          "You can't start or clear loads in RequestListener or"
309	              + " Target callbacks. If you're trying to start a fallback request when a load fails,"
310	              + " use RequestBuilder#error(RequestBuilder). Otherwise consider posting your into()"
311	              + " or clear() calls to the main thread using a Handler instead.");
312	    }
313	  }
