315	  /**
316	   * Cancels the current load if it is in progress, clears any resources held onto by the request
317	   * and replaces the loaded resource if the load completed with the placeholder.
318	   *
319	   * <p>Cleared requests can be restarted with a subsequent call to {@link #begin()}
320	   *
321	   * @see #cancel()
322	   */
323	  @Override
324	  public void clear() {
325	    Resource<R> toRelease = null;
326	    synchronized (requestLock) {
327	      assertNotCallingCallbacks();
328	      stateVerifier.throwIfRecycled();
329	      if (status == Status.CLEARED) {
330	        return;
331	      }
332	      cancel();
333	      // Resource must be released before canNotifyStatusChanged is called.
334	      if (resource != null) {
335	        toRelease = resource;
336	        resource = null;
337	      }
338	      if (canNotifyCleared()) {
339	        target.onLoadCleared(getPlaceholderDrawable());
340	      }
341	
342	      GlideTrace.endSectionAsync(TAG, cookie);
343	      status = Status.CLEARED;
344	    }
345	
346	    if (toRelease != null) {
347	      engine.release(toRelease);
348	    }
349	  }
