388	  @GuardedBy("requestLock")
389	  private Drawable getErrorDrawable() {
390	    if (errorDrawable == null) {
391	      errorDrawable = requestOptions.getErrorPlaceholder();
392	      if (errorDrawable == null && requestOptions.getErrorId() > 0) {
393	        errorDrawable = loadDrawable(requestOptions.getErrorId());
394	      }
395	    }
396	    return errorDrawable;
397	  }
