428	  @GuardedBy("requestLock")
429	  private void setErrorPlaceholder() {
430	    if (!canNotifyStatusChanged()) {
431	      return;
432	    }
433	
434	    Drawable error = null;
435	    if (model == null) {
436	      error = getFallbackDrawable();
437	    }
438	    // Either the model isn't null, or there was no fallback drawable set.
439	    if (error == null) {
440	      error = getErrorDrawable();
441	    }
442	    // The model isn't null, no fallback drawable was set or no error drawable was set.
443	    if (error == null) {
444	      error = getPlaceholderDrawable();
445	    }
446	    target.onLoadFailed(error);
447	  }
