449	  /** A callback method that should never be invoked directly. */
450	  @Override
451	  public void onSizeReady(int width, int height) {
452	    stateVerifier.throwIfRecycled();
453	    synchronized (requestLock) {
454	      if (IS_VERBOSE_LOGGABLE) {
455	        logV("Got onSizeReady in " + LogTime.getElapsedMillis(startTime));
456	      }
457	      if (status != Status.WAITING_FOR_SIZE) {
458	        return;
459	      }
460	      status = Status.RUNNING;
461	
462	      float sizeMultiplier = requestOptions.getSizeMultiplier();
463	      this.width = maybeApplySizeMultiplier(width, sizeMultiplier);
464	      this.height = maybeApplySizeMultiplier(height, sizeMultiplier);
465	
466	      if (IS_VERBOSE_LOGGABLE) {
467	        logV("finished setup for calling load in " + LogTime.getElapsedMillis(startTime));
468	      }
469	      loadStatus =
470	          engine.load(
471	              glideContext,
472	              model,
473	              requestOptions.getSignature(),
474	              this.width,
475	              this.height,
476	              requestOptions.getResourceClass(),
477	              transcodeClass,
478	              priority,
479	              requestOptions.getDiskCacheStrategy(),
480	              requestOptions.getTransformations(),
481	              requestOptions.isTransformationRequired(),
482	              requestOptions.isScaleOnlyOrNoTransform(),
483	              requestOptions.getOptions(),
484	              requestOptions.isMemoryCacheable(),
485	              requestOptions.getUseUnlimitedSourceGeneratorsPool(),
486	              requestOptions.getUseAnimationPool(),
487	              requestOptions.getOnlyRetrieveFromCache(),
488	              this,
489	              callbackExecutor);
490	
491	      // This is a hack that's only useful for testing right now where loads complete synchronously
492	      // even though under any executor running on any thread but the main thread, the load would
493	      // have completed asynchronously.
494	      if (status != Status.RUNNING) {
495	        loadStatus = null;
496	      }
497	      if (IS_VERBOSE_LOGGABLE) {
498	        logV("finished onSizeReady in " + LogTime.getElapsedMillis(startTime));
499	      }
500	    }
501	  }
502	
503	  private static int maybeApplySizeMultiplier(int size, float sizeMultiplier) {
504	    return size == Target.SIZE_ORIGINAL ? size : Math.round(sizeMultiplier * size);
505	  }
