608	  /**
609	   * Internal {@link #onResourceReady(Resource, DataSource, boolean)} where arguments are known to
610	   * be safe.
611	   *
612	   * @param resource original {@link Resource}, never <code>null</code>
613	   * @param result object returned by {@link Resource#get()}, checked for type and never <code>null
614	   *     </code>
615	   */
616	  // We're using experimental APIs...
617	  @SuppressWarnings({"deprecation", "PMD.UnusedFormalParameter"})
618	  @GuardedBy("requestLock")
619	  private void onResourceReady(
620	      Resource<R> resource, R result, DataSource dataSource, boolean isAlternateCacheKey) {
621	    // We must call isFirstReadyResource before setting status.
622	    boolean isFirstResource = isFirstReadyResource();
623	    status = Status.COMPLETE;
624	    this.resource = resource;
625	
626	    if (glideContext.getLogLevel() <= Log.DEBUG) {
627	      Log.d(
628	          GLIDE_TAG,
629	          "Finished loading "
630	              + result.getClass().getSimpleName()
631	              + " from "
632	              + dataSource
633	              + " for "
634	              + model
635	              + " with size ["
636	              + width
637	              + "x"
638	              + height
639	              + "] in "
640	              + LogTime.getElapsedMillis(startTime)
641	              + " ms");
642	    }
643	
644	    notifyRequestCoordinatorLoadSucceeded();
645	
646	    isCallingCallbacks = true;
647	    try {
648	      boolean anyListenerHandledUpdatingTarget = false;
649	      if (requestListeners != null) {
650	        for (RequestListener<R> listener : requestListeners) {
651	          anyListenerHandledUpdatingTarget |=
652	              listener.onResourceReady(result, model, target, dataSource, isFirstResource);
653	
654	          if (listener instanceof ExperimentalRequestListener) {
655	            ExperimentalRequestListener<R> experimentalRequestListener =
656	                (ExperimentalRequestListener<R>) listener;
657	            anyListenerHandledUpdatingTarget |=
658	                experimentalRequestListener.onResourceReady(
659	                    result, model, target, dataSource, isFirstResource, isAlternateCacheKey);
660	          }
661	        }
662	      }
663	      anyListenerHandledUpdatingTarget |=
664	          targetListener != null
665	              && targetListener.onResourceReady(result, model, target, dataSource, isFirstResource);
666	
667	      if (!anyListenerHandledUpdatingTarget) {
668	        Transition<? super R> animation = animationFactory.build(dataSource, isFirstResource);
669	        target.onResourceReady(result, animation);
670	      }
671	    } finally {
672	      isCallingCallbacks = false;
673	    }
674	
675	    GlideTrace.endSectionAsync(TAG, cookie);
676	  }
