690	  private void onLoadFailed(GlideException e, int maxLogLevel) {
691	    stateVerifier.throwIfRecycled();
692	    synchronized (requestLock) {
693	      e.setOrigin(requestOrigin);
694	      int logLevel = glideContext.getLogLevel();
695	      if (logLevel <= maxLogLevel) {
696	        Log.w(
697	            GLIDE_TAG,
698	            "Load failed for [" + model + "] with dimensions [" + width + "x" + height + "]",
699	            e);
700	        if (logLevel <= Log.INFO) {
701	          e.logRootCauses(GLIDE_TAG);
702	        }
703	      }
704	
705	      loadStatus = null;
706	      status = Status.FAILED;
707	
708	      notifyRequestCoordinatorLoadFailed();
709	
710	      isCallingCallbacks = true;
711	      try {
712	        // TODO: what if this is a thumbnail request?
713	        boolean anyListenerHandledUpdatingTarget = false;
714	        if (requestListeners != null) {
715	          for (RequestListener<R> listener : requestListeners) {
716	            anyListenerHandledUpdatingTarget |=
717	                listener.onLoadFailed(e, model, target, isFirstReadyResource());
718	          }
719	        }
720	        anyListenerHandledUpdatingTarget |=
721	            targetListener != null
722	                && targetListener.onLoadFailed(e, model, target, isFirstReadyResource());
723	
724	        if (!anyListenerHandledUpdatingTarget) {
725	          setErrorPlaceholder();
726	        }
727	      } finally {
728	        isCallingCallbacks = false;
729	      }
730	
731	      GlideTrace.endSectionAsync(TAG, cookie);
732	    }
733	  }
734	
735	  @Override
736	  public boolean isEquivalentTo(Request o) {
737	    if (!(o instanceof SingleRequest)) {
738	      return false;
739	    }
740	
741	    int localOverrideWidth;
742	    int localOverrideHeight;
743	    Object localModel;
744	    Class<?> localTranscodeClass;
745	    BaseRequestOptions<?> localRequestOptions;
746	    Priority localPriority;
747	    int localListenerCount;
748	    synchronized (requestLock) {
749	      localOverrideWidth = overrideWidth;
750	      localOverrideHeight = overrideHeight;
751	      localModel = model;
752	      localTranscodeClass = transcodeClass;
753	      localRequestOptions = requestOptions;
754	      localPriority = priority;
755	      localListenerCount = requestListeners != null ? requestListeners.size() : 0;
756	    }
757	
758	    SingleRequest<?> other = (SingleRequest<?>) o;
759	    int otherLocalOverrideWidth;
760	    int otherLocalOverrideHeight;
761	    Object otherLocalModel;
762	    Class<?> otherLocalTranscodeClass;
763	    BaseRequestOptions<?> otherLocalRequestOptions;
764	    Priority otherLocalPriority;
765	    int otherLocalListenerCount;
766	    synchronized (other.requestLock) {
767	      otherLocalOverrideWidth = other.overrideWidth;
768	      otherLocalOverrideHeight = other.overrideHeight;
769	      otherLocalModel = other.model;
770	      otherLocalTranscodeClass = other.transcodeClass;
771	      otherLocalRequestOptions = other.requestOptions;
772	      otherLocalPriority = other.priority;
773	      otherLocalListenerCount = other.requestListeners != null ? other.requestListeners.size() : 0;
774	    }
775	
776	    // If there's ever a case where synchronization matters for these values, something else has
777	    // gone wrong. It indicates that we'er comparing at least one recycled object, which has to be
778	    // protected against via other means. None of these values changes aside from object re-use.
779	    return localOverrideWidth == otherLocalOverrideWidth
780	        && localOverrideHeight == otherLocalOverrideHeight
781	        && Util.bothModelsNullEquivalentOrEquals(localModel, otherLocalModel)
782	        && localTranscodeClass.equals(otherLocalTranscodeClass)
783	        && Util.bothBaseRequestOptionsNullEquivalentOrEquals(
784	            localRequestOptions, otherLocalRequestOptions)
785	        && localPriority == otherLocalPriority
786	        // We do not want to require that RequestListeners implement equals/hashcode, so we
787	        // don't compare them using equals(). We can however, at least assert that the same
788	        // amount of request listeners are present in both requests.
789	        && localListenerCount == otherLocalListenerCount;
790	  }
791	
792	  private void logV(String message) {
793	    Log.v(TAG, message + " this: " + tag);
794	  }
