796	  @Override
797	  public String toString() {
798	    Object localModel;
799	    Class<?> localTranscodeClass;
800	    synchronized (requestLock) {
801	      localModel = model;
802	      localTranscodeClass = transcodeClass;
803	    }
804	    return super.toString()
805	        + "[model="
806	        + localModel
807	        + ", transcodeClass="
808	        + localTranscodeClass
809	        + "]";
810	  }
