243	  // We need to rethrow only CallbackException, but not other types of Throwables.
244	  @SuppressWarnings("PMD.AvoidRethrowingException")
245	  @Override
246	  public void run() {
247	    // This should be much more fine grained, but since Java's thread pool implementation silently
248	    // swallows all otherwise fatal exceptions, this will at least make it obvious to developers
249	    // that something is failing.
250	    GlideTrace.beginSectionFormat("DecodeJob#run(reason=%s, model=%s)", runReason, model);
251	    // Methods in the try statement can invalidate currentFetcher, so set a local variable here to
252	    // ensure that the fetcher is cleaned up either way.
253	    DataFetcher<?> localFetcher = currentFetcher;
254	    try {
255	      if (isCancelled) {
256	        notifyFailed();
257	        return;
258	      }
259	      runWrapped();
260	    } catch (CallbackException e) {
261	      // If a callback not controlled by Glide throws an exception, we should avoid the Glide
262	      // specific debug logic below.
263	      throw e;
264	    } catch (Throwable t) {
265	      // Catch Throwable and not Exception to handle OOMs. Throwables are swallowed by our
266	      // usage of .submit() in GlideExecutor so we're not silently hiding crashes by doing this. We
267	      // are however ensuring that our callbacks are always notified when a load fails. Without this
268	      // notification, uncaught throwables never notify the corresponding callbacks, which can cause
269	      // loads to silently hang forever, a case that's especially bad for users using Futures on
270	      // background threads.
271	      if (Log.isLoggable(TAG, Log.DEBUG)) {
272	        Log.d(
273	            TAG,
274	            "DecodeJob threw unexpectedly" + ", isCancelled: " + isCancelled + ", stage: " + stage,
275	            t);
276	      }
277	      // When we're encoding we've already notified our callback and it isn't safe to do so again.
278	      if (stage != Stage.ENCODE) {
279	        throwables.add(t);
280	        notifyFailed();
281	      }
282	      throw t;
283	    } finally {
284	      // Keeping track of the fetcher here and calling cleanup is excessively paranoid, we call
285	      // close in all cases anyway.
286	      if (localFetcher != null) {
287	        localFetcher.cleanup();
288	      }
289	      GlideTrace.endSection();
290	    }
291	  }
