293	  private void runWrapped() {
294	    switch (runReason) {
295	      case INITIALIZE:
296	        stage = getNextStage(Stage.INITIALIZE);
297	        currentGenerator = getNextGenerator();
298	        runGenerators();
299	        break;
300	      case SWITCH_TO_SOURCE_SERVICE:
301	        runGenerators();
302	        break;
303	      case DECODE_DATA:
304	        decodeFromRetrievedData();
305	        break;
306	      default:
307	        throw new IllegalStateException("Unrecognized run reason: " + runReason);
308	    }
309	  }
