311	  private DataFetcherGenerator getNextGenerator() {
312	    switch (stage) {
313	      case RESOURCE_CACHE:
314	        return new ResourceCacheGenerator(decodeHelper, this);
315	      case DATA_CACHE:
316	        return new DataCacheGenerator(decodeHelper, this);
317	      case SOURCE:
318	        return new SourceGenerator(decodeHelper, this);
319	      case FINISHED:
320	        return null;
321	      default:
322	        throw new IllegalStateException("Unrecognized stage: " + stage);
323	    }
324	  }
