326	  private void runGenerators() {
327	    currentThread = Thread.currentThread();
328	    startFetchTime = LogTime.getLogTime();
329	    boolean isStarted = false;
330	    while (!isCancelled
331	        && currentGenerator != null
332	        && !(isStarted = currentGenerator.startNext())) {
333	      stage = getNextStage(stage);
334	      currentGenerator = getNextGenerator();
335	
336	      if (stage == Stage.SOURCE) {
337	        reschedule(RunReason.SWITCH_TO_SOURCE_SERVICE);
338	        return;
339	      }
340	    }
341	    // We've run out of stages and generators, give up.
342	    if ((stage == Stage.FINISHED || isCancelled) && !isStarted) {
343	      notifyFailed();
344	    }
345	
346	    // Otherwise a generator started a new load and we expect to be called back in
347	    // onDataFetcherReady.
348	  }
