360	        Process.setThreadPriority(Process.myTid(), GlideExecutor.DEFAULT_PRIORITY);
361	      } catch (IllegalArgumentException | SecurityException e) {
362	        glideThreadPriorityOverride = null;
363	        if (Log.isLoggable(TAG, Log.VERBOSE)) {
364	          Log.v(
365	              TAG,
366	              "Failed to set thread priority; using default priority for any subsequent jobs.",
