401	  private Stage getNextStage(Stage current) {
402	    switch (current) {
403	      case INITIALIZE:
404	        return diskCacheStrategy.decodeCachedResource()
405	            ? Stage.RESOURCE_CACHE
406	            : getNextStage(Stage.RESOURCE_CACHE);
407	      case RESOURCE_CACHE:
408	        return diskCacheStrategy.decodeCachedData()
409	            ? Stage.DATA_CACHE
410	            : getNextStage(Stage.DATA_CACHE);
411	      case DATA_CACHE:
412	        // Skip loading from source if the user opted to only retrieve the resource from cache.
413	        return onlyRetrieveFromCache ? Stage.FINISHED : Stage.SOURCE;
414	      case SOURCE:
415	      case FINISHED:
416	        return Stage.FINISHED;
417	      default:
418	        throw new IllegalArgumentException("Unrecognized stage: " + current);
419	    }
420	  }
