470	  private void decodeFromRetrievedData() {
471	    if (Log.isLoggable(TAG, Log.VERBOSE)) {
472	      logWithTimeAndKey(
473	          "Retrieved data",
474	          startFetchTime,
475	          "data: "
476	              + currentData
477	              + ", cache key: "
478	              + currentSourceKey
479	              + ", fetcher: "
480	              + currentFetcher);
481	    }
482	    if (experiments.isEnabled(OverrideGlideThreadPriority.class)
483	        && glideThreadPriorityOverride != null
484	        && glideThreadPriorityOverride.get() != null) {
485	      try {
486	        Process.setThreadPriority(Process.myTid(), glideThreadPriorityOverride.get().intValue());
487	      } catch (IllegalArgumentException | SecurityException e) {
488	        glideThreadPriorityOverride = null;
489	        if (Log.isLoggable(TAG, Log.VERBOSE)) {
490	          Log.v(
491	              TAG,
492	              "Failed to set thread priority; using default priority for any subsequent jobs.",
493	              e);
494	        }
495	      }
496	    }
497	    Resource<R> resource = null;
498	    try {
499	      resource = decodeFromData(currentFetcher, currentData, currentDataSource);
500	    } catch (GlideException e) {
501	      e.setLoggingDetails(currentAttemptingKey, currentDataSource);
502	      throwables.add(e);
503	    }
504	    if (resource != null) {
505	      notifyEncodeAndRelease(resource, currentDataSource, isLoadingFromAlternateCacheKey);
506	    } else {
507	      runGenerators();
508	    }
