511	  private void notifyEncodeAndRelease(
512	      Resource<R> resource, DataSource dataSource, boolean isLoadedFromAlternateCacheKey) {
513	    GlideTrace.beginSection("DecodeJob.notifyEncodeAndRelease");
514	    try {
515	      if (resource instanceof Initializable) {
516	        ((Initializable) resource).initialize();
517	      }
518	
519	      Resource<R> result = resource;
520	      LockedResource<R> lockedResource = null;
521	      if (deferredEncodeManager.hasResourceToEncode()) {
522	        lockedResource = LockedResource.obtain(resource);
523	        result = lockedResource;
524	      }
525	
526	      notifyComplete(result, dataSource, isLoadedFromAlternateCacheKey);
527	
528	      stage = Stage.ENCODE;
529	      try {
530	        if (deferredEncodeManager.hasResourceToEncode()) {
531	          deferredEncodeManager.encode(diskCacheProvider, options);
532	        }
533	      } finally {
534	        if (lockedResource != null) {
535	          lockedResource.unlock();
536	        }
537	      }
538	      // Call onEncodeComplete outside the finally block so that it's not called if the encode
539	      // process
540	      // throws.
541	      onEncodeComplete();
542	    } finally {
543	      GlideTrace.endSection();
