547	  private <Data> Resource<R> decodeFromData(
548	      DataFetcher<?> fetcher, Data data, DataSource dataSource) throws GlideException {
549	    try {
550	      if (data == null) {
551	        return null;
552	      }
553	      long startTime = LogTime.getLogTime();
554	      Resource<R> result = decodeFromFetcher(data, dataSource);
555	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
556	        logWithTimeAndKey("Decoded result " + result, startTime);
557	      }
558	      return result;
559	    } finally {
560	      fetcher.cleanup();
561	    }
562	  }
