564	  @SuppressWarnings("unchecked")
565	  private <Data> Resource<R> decodeFromFetcher(Data data, DataSource dataSource)
566	      throws GlideException {
567	    LoadPath<Data, ?, R> path = decodeHelper.getLoadPath((Class<Data>) data.getClass());
568	    return runLoadPath(data, dataSource, path);
569	  }
