571	  @NonNull
572	  private Options getOptionsWithHardwareConfig(DataSource dataSource) {
573	    Options options = this.options;
574	    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) {
575	      return options;
576	    }
577	
578	    boolean isHardwareConfigSafe =
579	        dataSource == DataSource.RESOURCE_DISK_CACHE || decodeHelper.isScaleOnlyOrNoTransform();
580	    Boolean isHardwareConfigAllowed = options.get(Downsampler.ALLOW_HARDWARE_CONFIG);
581	
582	    // If allow hardware config is defined, we can use it if it's set to false or if it's safe to
583	    // use the hardware config for the request.
584	    if (isHardwareConfigAllowed != null && (!isHardwareConfigAllowed || isHardwareConfigSafe)) {
585	      return options;
586	    }
587	
588	    // If allow hardware config is undefined or is set to true but it's unsafe for us to use the
589	    // hardware config for this request, we need to override the config.
590	    options = new Options();
591	    options.putAll(this.options);
592	    options.set(Downsampler.ALLOW_HARDWARE_CONFIG, isHardwareConfigSafe);
593	
594	    return options;
595	  }
