597	  private <Data, ResourceType> Resource<R> runLoadPath(
598	      Data data, DataSource dataSource, LoadPath<Data, ResourceType, R> path)
599	      throws GlideException {
600	    Options options = getOptionsWithHardwareConfig(dataSource);
601	    DataRewinder<Data> rewinder = glideContext.getRegistry().getRewinder(data);
602	    try {
603	      // ResourceType in DecodeCallback below is required for compilation to work with gradle.
604	      return path.load(
605	          rewinder, options, width, height, new DecodeCallback<ResourceType>(dataSource));
606	    } finally {
607	      rewinder.cleanup();
608	    }
609	  }
