634	  @Synthetic
635	  @NonNull
636	  <Z> Resource<Z> onResourceDecoded(DataSource dataSource, @NonNull Resource<Z> decoded) {
637	    @SuppressWarnings("unchecked")
638	    Class<Z> resourceSubClass = (Class<Z>) decoded.get().getClass();
639	    Transformation<Z> appliedTransformation = null;
640	    Resource<Z> transformed = decoded;
641	    if (dataSource != DataSource.RESOURCE_DISK_CACHE) {
642	      appliedTransformation = decodeHelper.getTransformation(resourceSubClass);
643	      if (shouldBypassSoftwareTransformation(decoded, appliedTransformation)) {
644	        if (Log.isLoggable(TAG, Log.VERBOSE)) {
645	          Log.v(
646	              TAG,
647	              "Bypassing software transformations for resource: "
648	                  + decoded.get()
649	                  + " with transformation: "
650	                  + appliedTransformation);
651	        }
652	      } else {
653	        transformed = appliedTransformation.transform(glideContext, decoded, width, height);
654	      }
655	    }
656	    // TODO: Make this the responsibility of the Transformation.
657	    if (!decoded.equals(transformed)) {
658	      decoded.recycle();
659	    }
660	
661	    final EncodeStrategy encodeStrategy;
662	    final ResourceEncoder<Z> encoder;
663	    if (decodeHelper.isResourceEncoderAvailable(transformed)) {
664	      encoder = decodeHelper.getResultEncoder(transformed);
665	      encodeStrategy = encoder.getEncodeStrategy(options);
666	    } else {
667	      encoder = null;
668	      encodeStrategy = EncodeStrategy.NONE;
669	    }
670	
671	    Resource<Z> result = transformed;
672	    boolean isFromAlternateCacheKey = !decodeHelper.isSourceKey(currentSourceKey);
673	    boolean isResourceCacheable =
674	        isResourceCacheable(isFromAlternateCacheKey, dataSource, encodeStrategy, transformed);
675	    if (isResourceCacheable) {
676	      if (encoder == null) {
677	        throw new Registry.NoResultEncoderAvailableException(transformed.get().getClass());
678	      }
679	      final Key key;
680	      switch (encodeStrategy) {
681	        case SOURCE:
682	          key = new DataCacheKey(currentSourceKey, signature);
683	          break;
684	        case TRANSFORMED:
685	          key =
686	              new ResourceCacheKey(
687	                  decodeHelper.getArrayPool(),
688	                  currentSourceKey,
689	                  signature,
690	                  width,
691	                  height,
692	                  appliedTransformation,
693	                  resourceSubClass,
694	                  options);
695	          break;
696	        default:
697	          throw new IllegalArgumentException("Unknown strategy: " + encodeStrategy);
698	      }
699	
700	      LockedResource<Z> lockedResult = LockedResource.obtain(transformed);
701	      deferredEncodeManager.init(key, encoder, lockedResult);
702	      result = lockedResult;
703	    }
704	    return result;
705	  }
