707	  /**
708	   * Returns {@code true} if the decoded and transformed resource is eligible to be written to the
709	   * resource disk cache.
710	   *
711	   * <p>When {@link GlideBuilder.BypassResourceDiskCacheForHardwareBitmaps} is enabled, resources
712	   * backed by {@link Bitmap.Config#HARDWARE} bitmaps are never written. Compressing a hardware
713	   * bitmap requires the framework to copy its pixels out of graphics memory into a software bitmap
714	   * ({@code RenderProxy#copyHWBitmapInto}). That copy runs on this job's thread after the resource
715	   * has been delivered, round-trips through the RenderThread (contending with frame rendering),
716	   * holds the {@link LockedResource} until it finishes, and transiently allocates a second,
717	   * full-size copy of the image in native memory.
718	   */
719	  private <Z> boolean isResourceCacheable(
720	      boolean isFromAlternateCacheKey,
721	      DataSource dataSource,
722	      EncodeStrategy encodeStrategy,
723	      Resource<Z> transformed) {
724	    if (!diskCacheStrategy.isResourceCacheable(
725	        isFromAlternateCacheKey, dataSource, encodeStrategy)) {
726	      return false;
727	    }
728	    if (experiments.isEnabled(GlideBuilder.BypassResourceDiskCacheForHardwareBitmaps.class)
729	        && isHardwareBitmap(transformed)) {
730	      return false;
731	    }
732	    return true;
733	  }
734	
735	  private static boolean isHardwareBitmap(Resource<?> resource) {
736	    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) {
737	      return false;
738	    }
739	    Object content = resource.get();
740	    Bitmap bitmap = null;
741	    if (content instanceof Bitmap) {
742	      bitmap = (Bitmap) content;
743	    } else if (content instanceof BitmapDrawable) {
744	      bitmap = ((BitmapDrawable) content).getBitmap();
745	    }
746	    return bitmap != null && bitmap.getConfig() == Bitmap.Config.HARDWARE;
747	  }
748	
749	  /**
750	   * Returns {@code true} if we should bypass applying software transformations to the decoded
751	   * resource.
752	   *
753	   * <p>This is only true if the resource is a hardware bitmap, and both ALLOW_HARDWARE_CONFIG and
754	   * BYPASS_TRANSFORMATIONS_FOR_HARDWARE_BITMAPS options are enabled.
755	   */
756	  private <Z> boolean shouldBypassSoftwareTransformation(
757	      Resource<Z> decoded, Transformation<Z> transformation) {
758	    if (!Boolean.TRUE.equals(options.get(Downsampler.BYPASS_TRANSFORMATIONS_FOR_HARDWARE_BITMAPS))) {
759	      return false;
760	    }
761	    if (!Boolean.TRUE.equals(options.get(Downsampler.ALLOW_HARDWARE_CONFIG))) {
762	      return false;
763	    }
764	
765	    return isHardwareBitmap(decoded);
766	  }
