784	  /**
785	   * Responsible for indicating when it is safe for the job to be cleared and returned to the pool.
786	   */
787	  private static class ReleaseManager {
788	    private boolean isReleased;
789	    private boolean isEncodeComplete;
790	    private boolean isFailed;
791	
792	    @Synthetic
793	    ReleaseManager() {}
794	
795	    synchronized boolean release(boolean isRemovedFromQueue) {
796	      isReleased = true;
797	      return isComplete(isRemovedFromQueue);
798	    }
799	
800	    synchronized boolean onEncodeComplete() {
801	      isEncodeComplete = true;
802	      return isComplete(false /*isRemovedFromQueue*/);
803	    }
804	
805	    synchronized boolean onFailed() {
806	      isFailed = true;
807	      return isComplete(false /*isRemovedFromQueue*/);
808	    }
809	
810	    synchronized void reset() {
811	      isEncodeComplete = false;
812	      isReleased = false;
813	      isFailed = false;
814	    }
815	
816	    private boolean isComplete(boolean isRemovedFromQueue) {
817	      return (isFailed || isRemovedFromQueue || isEncodeComplete) && isReleased;
818	    }
819	  }
