821	  /**
822	   * Allows transformed resources to be encoded after the transcoded result is already delivered to
823	   * requestors.
824	   */
825	  private static class DeferredEncodeManager<Z> {
826	    private Key key;
827	    private ResourceEncoder<Z> encoder;
828	    private LockedResource<Z> toEncode;
829	
830	    @Synthetic
831	    DeferredEncodeManager() {}
832	
833	    // We just need the encoder and resource type to match, which this will enforce.
834	    @SuppressWarnings("unchecked")
835	    <X> void init(Key key, ResourceEncoder<X> encoder, LockedResource<X> toEncode) {
836	      this.key = key;
837	      this.encoder = (ResourceEncoder<Z>) encoder;
838	      this.toEncode = (LockedResource<Z>) toEncode;
839	    }
840	
841	    void encode(DiskCacheProvider diskCacheProvider, Options options) {
842	      GlideTrace.beginSection("DecodeJob.encode");
843	      try {
844	        diskCacheProvider
845	            .getDiskCache()
846	            .put(key, new DataCacheWriter<>(encoder, toEncode, options));
847	      } finally {
848	        toEncode.unlock();
849	        GlideTrace.endSection();
850	      }
851	    }
852	
853	    boolean hasResourceToEncode() {
854	      return toEncode != null;
855	    }
856	
857	    void clear() {
858	      key = null;
859	      encoder = null;
860	      toEncode = null;
861	    }
862	  }
