18	/**
19	 * An {@link com.bumptech.glide.load.engine.bitmap_recycle.BitmapPool} implementation that uses an
20	 * {@link com.bumptech.glide.load.engine.bitmap_recycle.LruPoolStrategy} to bucket {@link Bitmap}s
21	 * and then uses an LRU eviction policy to evict {@link android.graphics.Bitmap}s from the least
22	 * recently used bucket in order to keep the pool below a given maximum size limit.
23	 */
24	public class LruBitmapPool implements BitmapPool {
25	  private static final String TAG = "LruBitmapPool";
26	  private static final Bitmap.Config DEFAULT_CONFIG = Bitmap.Config.ARGB_8888;
27	
28	  private final LruPoolStrategy strategy;
29	  private final Set<Bitmap.Config> allowedConfigs;
30	  private final long initialMaxSize;
31	  private final BitmapTracker tracker;
32	
33	  private long maxSize;
34	  private long currentSize;
35	  private int hits;
36	  private int misses;
37	  private int puts;
38	  private int evictions;
39	
40	  // Exposed for testing only.
41	  LruBitmapPool(long maxSize, LruPoolStrategy strategy, Set<Bitmap.Config> allowedConfigs) {
42	    this.initialMaxSize = maxSize;
43	    this.maxSize = maxSize;
44	    this.strategy = strategy;
45	    this.allowedConfigs = allowedConfigs;
46	    this.tracker = new NullBitmapTracker();
47	  }
48	
49	  /**
50	   * Constructor for LruBitmapPool.
51	   *
52	   * @param maxSize The initial maximum size of the pool in bytes.
53	   */
54	  public LruBitmapPool(long maxSize) {
55	    this(maxSize, getDefaultStrategy(), getDefaultAllowedConfigs());
56	  }
57	
58	  /**
59	   * Constructor for LruBitmapPool.
60	   *
61	   * @param maxSize The initial maximum size of the pool in bytes.
62	   * @param allowedConfigs A white listed put of {@link android.graphics.Bitmap.Config} that are
63	   *     allowed to be put into the pool. Configs not in the allowed put will be rejected.
64	   */
65	  // Public API.
66	  @SuppressWarnings("unused")
67	  public LruBitmapPool(long maxSize, Set<Bitmap.Config> allowedConfigs) {
68	    this(maxSize, getDefaultStrategy(), allowedConfigs);
69	  }
70	
71	  /** Returns the number of cache hits for bitmaps in the pool. */
72	  public long hitCount() {
73	    return hits;
74	  }
75	
76	  /** Returns the number of cache misses for bitmaps in the pool. */
77	  public long missCount() {
78	    return misses;
79	  }
80	
81	  /** Returns the number of bitmaps that have been evicted from the pool. */
82	  public long evictionCount() {
83	    return evictions;
84	  }
85	
