91	  @Override
92	  public long getMaxSize() {
93	    return maxSize;
94	  }
95	
96	  @Override
97	  public synchronized void setSizeMultiplier(float sizeMultiplier) {
98	    maxSize = Math.round(initialMaxSize * sizeMultiplier);
99	    evict();
100	  }
101	
102	  @Override
103	  public synchronized void put(Bitmap bitmap) {
104	    if (bitmap == null) {
105	      throw new NullPointerException("Bitmap must not be null");
106	    }
107	    if (bitmap.isRecycled()) {
108	      throw new IllegalStateException("Cannot pool recycled bitmap");
109	    }
110	    if (!bitmap.isMutable()
111	        || strategy.getSize(bitmap) > maxSize
112	        || !allowedConfigs.contains(bitmap.getConfig())) {
113	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
114	        Log.v(
115	            TAG,
116	            "Reject bitmap from pool"
117	                + ", bitmap: "
118	                + strategy.logBitmap(bitmap)
119	                + ", is mutable: "
120	                + bitmap.isMutable()
121	                + ", is allowed config: "
122	                + allowedConfigs.contains(bitmap.getConfig()));
123	      }
124	      bitmap.recycle();
125	      return;
126	    }
127	
128	    final int size = strategy.getSize(bitmap);
129	    strategy.put(bitmap);
130	    tracker.add(bitmap);
131	
132	    puts++;
133	    currentSize += size;
134	
135	    if (Log.isLoggable(TAG, Log.VERBOSE)) {
136	      Log.v(TAG, "Put bitmap in pool=" + strategy.logBitmap(bitmap));
137	    }
138	    dump();
139	
140	    evict();
141	  }
142	
143	  private void evict() {
144	    trimToSize(maxSize);
145	  }
