174	  private static void assertNotHardwareConfig(Bitmap.Config config) {
175	    // Avoid short circuiting on sdk int since it breaks on some versions of Android.
176	    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) {
177	      return;
178	    }
