189	  @Nullable
190	  private synchronized Bitmap getDirtyOrNull(
191	      int width, int height, @Nullable Bitmap.Config config) {
192	    assertNotHardwareConfig(config);
193	    // Config will be null for non public config types, which can lead to transformations naively
194	    // passing in null as the requested config here. See issue #194.
195	    final Bitmap result = strategy.get(width, height, config != null ? config : DEFAULT_CONFIG);
196	    if (result == null) {
