198	        Log.d(TAG, "Missing bitmap=" + strategy.logBitmap(width, height, config));
199	      }
200	      misses++;
201	    } else {
202	      hits++;
203	      currentSize -= strategy.getSize(result);
204	      tracker.remove(result);
205	      normalize(result);
