254	  private synchronized void trimToSize(long size) {
255	    while (currentSize > size) {
256	      final Bitmap removed = strategy.removeLast();
257	      // TODO: This shouldn't ever happen, see #331.
258	      if (removed == null) {
259	        if (Log.isLoggable(TAG, Log.WARN)) {
260	          Log.w(TAG, "Size mismatch, resetting");
261	          dumpUnchecked();
262	        }
263	        currentSize = 0;
264	        return;
265	      }
266	      tracker.remove(removed);
267	      currentSize -= strategy.getSize(removed);
268	      evictions++;
269	      if (Log.isLoggable(TAG, Log.DEBUG)) {
270	        Log.d(TAG, "Evicting bitmap=" + strategy.logBitmap(removed));
271	      }
272	      dump();
273	      removed.recycle();
274	    }
275	  }
