196	  @VisibleForTesting
197	  static final class Key implements Poolable {
198	    private final KeyPool pool;
199	
200	    @Synthetic int size;
201	    private Bitmap.Config config;
202	
203	    public Key(KeyPool pool) {
204	      this.pool = pool;
205	    }
206	
207	    @VisibleForTesting
208	    Key(KeyPool pool, int size, Bitmap.Config config) {
209	      this(pool);
210	      init(size, config);
211	    }
212	
213	    public void init(int size, Bitmap.Config config) {
214	      this.size = size;
215	      this.config = config;
216	    }
217	
218	    @Override
219	    public void offer() {
220	      pool.offer(this);
221	    }
222	
223	    @Override
224	    public String toString() {
225	      return getBitmapString(size, config);
226	    }
227	
228	    @Override
229	    public boolean equals(Object o) {
230	      if (o instanceof Key) {
231	        Key other = (Key) o;
232	        return size == other.size && Util.bothNullOrEqual(config, other.config);
233	      }
234	      return false;
235	    }
236	
237	    @Override
238	    public int hashCode() {
239	      int result = size;
240	      result = 31 * result + (config != null ? config.hashCode() : 0);
241	      return result;
242	    }
243	  }
244	
245	  @Synthetic
246	  static String getBitmapString(int size, Bitmap.Config config) {
247	    return "[" + size + "](" + config + ")";
248	  }
249	
250	  private static Bitmap.Config[] getInConfigs(Bitmap.Config requested) {
251	    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
252	      if (Bitmap.Config.RGBA_F16.equals(requested)) { // NOPMD - Avoid short circuiting sdk checks.
253	        return RGBA_F16_IN_CONFIGS;
254	      }
255	    }
256	
257	    switch (requested) {
258	      case ARGB_8888:
259	        return ARGB_8888_IN_CONFIGS;
260	      case RGB_565:
261	        return RGB_565_IN_CONFIGS;
262	      case ARGB_4444:
263	        return ARGB_4444_IN_CONFIGS;
264	      case ALPHA_8:
265	        return ALPHA_8_IN_CONFIGS;
266	      default:
267	        return new Bitmap.Config[] {requested};
268	    }
269	  }
