345	  // warning seems to be false positive.
346	  @SuppressWarnings({
347	    "WeakerAccess",
348	    "PMD.AvoidInstantiatingObjectsInLoops",
349	    "PMD.AccessorMethodGeneration"
350	  })
351	  @Synthetic
352	  void notifyCallbacksOfException() {
353	    ResourceCallbacksAndExecutors copy;
354	    Key localKey;
355	    synchronized (this) {
356	      stateVerifier.throwIfRecycled();
357	      if (isCancelled) {
358	        release();
359	        return;
360	      }
361	      if (cbs.isEmpty()) {
362	        throw new IllegalStateException("Received an exception without any callbacks to notify");
363	      }
364	      if (hasLoadFailed) {
365	        throw new IllegalStateException("Already failed once");
366	      }
367	      hasLoadFailed = true;
368	
369	      localKey = key;
370	
371	      copy = cbs.copy();
372	      // One for each callback below, plus one for ourselves so that we finish if a callback runs on
373	      // another thread before we finish scheduling all of them.
374	      incrementPendingCallbacks(copy.size() + 1);
375	    }
376	
377	    engineJobListener.onEngineJobComplete(this, localKey, /* resource= */ null);
378	
379	    for (ResourceCallbackAndExecutor entry : copy) {
380	      entry.executor.execute(new CallLoadFailed(entry.cb));
381	    }
382	    decrementPendingCallbacks();
383	  }
