391	  private class CallLoadFailed implements Runnable {
392	
393	    private final ResourceCallback cb;
394	
395	    CallLoadFailed(ResourceCallback cb) {
396	      this.cb = cb;
397	    }
398	
399	    @Override
400	    public void run() {
401	      // Make sure we always acquire the request lock, then the EngineJob lock to avoid deadlock
402	      // (b/136032534).
403	      synchronized (cb.getLock()) {
404	        synchronized (EngineJob.this) {
405	          if (cbs.contains(cb)) {
406	            callCallbackOnLoadFailed(cb);
407	          }
408	
409	          decrementPendingCallbacks();
410	        }
411	      }
412	    }
413	  }
