415	  private class CallResourceReady implements Runnable {
416	
417	    private final ResourceCallback cb;
418	
419	    CallResourceReady(ResourceCallback cb) {
420	      this.cb = cb;
421	    }
422	
423	    @Override
424	    public void run() {
425	      // Make sure we always acquire the request lock, then the EngineJob lock to avoid deadlock
426	      // (b/136032534).
427	      synchronized (cb.getLock()) {
428	        synchronized (EngineJob.this) {
429	          if (cbs.contains(cb)) {
430	            // Acquire for this particular callback.
431	            engineResource.acquire();
432	            callCallbackOnResourceReady(cb);
433	            removeCallback(cb);
