63	    // Either an application context or we're on a background thread.
64	    if (applicationManager == null) {
65	      synchronized (this) {
66	        if (applicationManager == null) {
67	          // Normally pause/resume is taken care of by the fragment we add to the fragment or
68	          // activity. However, in this case since the manager attached to the application will not
69	          // receive lifecycle events, we must force the manager to start resumed using
70	          // ApplicationLifecycle.
