160	    if (Util.isOnBackgroundThread()) {
161	      return get(view.getContext().getApplicationContext());
162	    }
163	
164	    Preconditions.checkNotNull(view);
165	    Preconditions.checkNotNull(
166	        view.getContext(), "Unable to obtain a request manager for a view without a Context");
167	    Activity activity = findActivity(view.getContext());
168	    // The view might be somewhere else, like a service.
169	    if (activity == null) {
