186	  private static void findAllSupportFragmentsWithViews(
187	      @Nullable Collection<Fragment> topLevelFragments, @NonNull Map<View, Fragment> result) {
188	    if (topLevelFragments == null) {
189	      return;
190	    }
191	    for (Fragment fragment : topLevelFragments) {
192	      // getFragment()s in the support FragmentManager may contain null values, see #1991.
193	      if (fragment == null || fragment.getView() == null) {
194	        continue;
195	      }
196	      result.put(fragment.getView(), fragment);
197	      findAllSupportFragmentsWithViews(fragment.getChildFragmentManager().getFragments(), result);
198	    }
199	  }
