201	  @Nullable
202	  private Fragment findSupportFragment(@NonNull View target, @NonNull FragmentActivity activity) {
203	    tempViewToSupportFragment.clear();
204	    findAllSupportFragmentsWithViews(
205	        activity.getSupportFragmentManager().getFragments(), tempViewToSupportFragment);
206	    Fragment result = null;
207	    View activityRoot = activity.findViewById(android.R.id.content);
208	    View current = target;
209	    while (!current.equals(activityRoot)) {
210	      result = tempViewToSupportFragment.get(current);
211	      if (result != null) {
212	        break;
213	      }
214	      if (current.getParent() instanceof View) {
215	        current = (View) current.getParent();
216	      } else {
217	        break;
218	      }
219	    }
220	
221	    tempViewToSupportFragment.clear();
222	    return result;
223	  }
