143	  /**
144	   * Starts a load for the given arguments.
145	   *
146	   * <p>Must be called on the main thread.
147	   *
148	   * <p>The flow for any request is as follows:
149	   *
150	   * <ul>
151	   *   <li>Check the current set of actively used resources, return the active resource if present,
152	   *       and move any newly inactive resources into the memory cache.
153	   *   <li>Check the memory cache and provide the cached resource if present.
154	   *   <li>Check the current set of in progress loads and add the cb to the in progress load if one
155	   *       is present.
156	   *   <li>Start a new load.
157	   * </ul>
158	   *
159	   * <p>Active resources are those that have been provided to at least one request and have not yet
160	   * been released. Once all consumers of a resource have released that resource, the resource then
161	   * goes to cache. If the resource is ever returned to a new consumer from cache, it is re-added to
162	   * the active resources. If the resource is evicted from the cache, its resources are recycled and
163	   * re-used if possible and the resource is discarded. There is no strict requirement that
164	   * consumers release their resources so active resources are held weakly.
165	   *
166	   * @param width The target width in pixels of the desired resource.
167	   * @param height The target height in pixels of the desired resource.
168	   * @param cb The callback that will be called when the load completes.
169	   */
170	  public <R> LoadStatus load(
171	      GlideContext glideContext,
172	      Object model,
173	      Key signature,
174	      int width,
175	      int height,
176	      Class<?> resourceClass,
177	      Class<R> transcodeClass,
178	      Priority priority,
179	      DiskCacheStrategy diskCacheStrategy,
180	      Map<Class<?>, Transformation<?>> transformations,
181	      boolean isTransformationRequired,
182	      boolean isScaleOnlyOrNoTransform,
183	      Options options,
184	      boolean isMemoryCacheable,
185	      boolean useUnlimitedSourceExecutorPool,
186	      boolean useAnimationPool,
187	      boolean onlyRetrieveFromCache,
188	      ResourceCallback cb,
189	      Executor callbackExecutor) {
190	    long startTime = VERBOSE_IS_LOGGABLE ? LogTime.getLogTime() : 0;
191	
192	    EngineKey key =
193	        keyFactory.buildKey(
194	            model,
195	            signature,
196	            width,
197	            height,
198	            transformations,
199	            resourceClass,
200	            transcodeClass,
201	            options);
202	
203	    boolean isReleaseRaceFixEnabled =
204	        glideContext.getExperiments().isEnabled(EnableActiveResourceReleaseRaceFix.class);
205	
206	    EngineResource<?> memoryResource;
207	    synchronized (this) {
208	      memoryResource = loadFromMemory(key, isMemoryCacheable, isReleaseRaceFixEnabled, startTime);
209	
210	      if (memoryResource == null) {
211	        return waitForExistingOrStartNewJob(
212	            glideContext,
213	            model,
214	            signature,
215	            width,
216	            height,
217	            resourceClass,
218	            transcodeClass,
219	            priority,
220	            diskCacheStrategy,
221	            transformations,
222	            isTransformationRequired,
223	            isScaleOnlyOrNoTransform,
224	            options,
225	            isMemoryCacheable,
226	            useUnlimitedSourceExecutorPool,
227	            useAnimationPool,
228	            onlyRetrieveFromCache,
229	            cb,
230	            callbackExecutor,
231	            key,
232	            startTime);
233	      }
234	    }
235	
236	    // Avoid calling back while holding the engine lock, doing so makes it easier for callers to
237	    // deadlock.
238	    cb.onResourceReady(
239	        memoryResource, DataSource.MEMORY_CACHE, /* isLoadedFromAlternateCacheKey= */ false);
240	    return null;
241	  }
242	
243	  private <R> LoadStatus waitForExistingOrStartNewJob(
244	      GlideContext glideContext,
245	      Object model,
246	      Key signature,
247	      int width,
248	      int height,
249	      Class<?> resourceClass,
250	      Class<R> transcodeClass,
251	      Priority priority,
252	      DiskCacheStrategy diskCacheStrategy,
253	      Map<Class<?>, Transformation<?>> transformations,
254	      boolean isTransformationRequired,
255	      boolean isScaleOnlyOrNoTransform,
256	      Options options,
257	      boolean isMemoryCacheable,
258	      boolean useUnlimitedSourceExecutorPool,
259	      boolean useAnimationPool,
260	      boolean onlyRetrieveFromCache,
261	      ResourceCallback cb,
262	      Executor callbackExecutor,
263	      EngineKey key,
264	      long startTime) {
265	
266	    EngineJob<?> current = jobs.get(key, onlyRetrieveFromCache);
267	    if (current != null) {
268	      current.addCallback(cb, callbackExecutor);
269	      if (VERBOSE_IS_LOGGABLE) {
270	        logWithTimeAndKey("Added to existing load", startTime, key);
271	      }
272	      return new LoadStatus(cb, current);
273	    }
274	
275	    EngineJob<R> engineJob =
276	        engineJobFactory.build(
277	            key,
278	            isMemoryCacheable,
279	            useUnlimitedSourceExecutorPool,
280	            useAnimationPool,
281	            onlyRetrieveFromCache);
282	
283	    DecodeJob<R> decodeJob =
284	        decodeJobFactory.build(
285	            glideContext,
286	            model,
287	            key,
288	            signature,
289	            width,
290	            height,
291	            resourceClass,
292	            transcodeClass,
293	            priority,
294	            diskCacheStrategy,
295	            transformations,
296	            isTransformationRequired,
297	            isScaleOnlyOrNoTransform,
298	            onlyRetrieveFromCache,
299	            options,
300	            engineJob);
301	
302	    jobs.put(key, engineJob);
303	
304	    engineJob.addCallback(cb, callbackExecutor);
305	    engineJob.start(decodeJob);
306	
307	    if (VERBOSE_IS_LOGGABLE) {
308	      logWithTimeAndKey("Started new load", startTime, key);
309	    }
310	    return new LoadStatus(cb, engineJob);
311	  }
312	
313	  @Nullable
314	  private EngineResource<?> loadFromMemory(
315	      EngineKey key, boolean isMemoryCacheable, boolean isReleaseRaceFixEnabled, long startTime) {
316	    if (!isMemoryCacheable) {
317	      return null;
318	    }
319	
320	    EngineResource<?> active = loadFromActiveResources(key, isReleaseRaceFixEnabled);
321	    if (active != null) {
322	      if (VERBOSE_IS_LOGGABLE) {
323	        logWithTimeAndKey("Loaded resource from active resources", startTime, key);
324	      }
325	      if (Log.isLoggable(GLIDE_MEMORY_TRACKING_TAG, Log.DEBUG)) {
326	        logCacheHit("active", key, active);
327	      }
328	      return active;
329	    }
330	
331	    EngineResource<?> cached = loadFromCache(key);
332	    if (cached != null) {
333	      if (VERBOSE_IS_LOGGABLE) {
334	        logWithTimeAndKey("Loaded resource from cache", startTime, key);
335	      }
336	      if (Log.isLoggable(GLIDE_MEMORY_TRACKING_TAG, Log.DEBUG)) {
337	        logCacheHit("cache", key, cached);
338	      }
339	      return cached;
340	    }
341	
342	    return null;
343	  }
344	
345	  private static void logWithTimeAndKey(String log, long startTime, Key key) {
346	    Log.v(TAG, log + " in " + LogTime.getElapsedMillis(startTime) + "ms, key: " + key);
347	  }
348	
349	  /**
350	   * Logs memory cache hits (from active resources or memory cache). Handles both raw Bitmaps and
351	   * Bitmaps wrapped inside BitmapDrawable resources.
352	   */
353	  private static void logCacheHit(String source, EngineKey key, EngineResource<?> resource) {
354	    if (!Log.isLoggable(GLIDE_MEMORY_TRACKING_TAG, Log.DEBUG)) {
355	      return;
356	    }
357	
358	    Object data = resource.get();
359	    Bitmap bitmap = null;
360	    if (data instanceof Bitmap) {
361	      bitmap = (Bitmap) data;
362	    } else if (data instanceof android.graphics.drawable.BitmapDrawable) {
363	      bitmap = ((android.graphics.drawable.BitmapDrawable) data).getBitmap();
364	    }
365	    if (bitmap == null) {
366	      return;
367	    }
368	
369	    int bitmapIdentity = System.identityHashCode(bitmap);
370	    Log.d(
371	        GLIDE_MEMORY_TRACKING_TAG,
372	        "Engine [Device: "
373	            + android.os.Build.DEVICE
374	            + "]: Loaded bitmap [ID: "
375	            + bitmapIdentity
376	            + "] from memory cache ("
377	            + source
378	            + "). Size: ["
379	            + bitmap.getWidth()
380	            + "x"
381	            + bitmap.getHeight()
382	            + "] ("
383	            + Util.getBitmapByteSize(bitmap)
384	            + " bytes)");
385	  }
386	
387	  @Nullable
388	  private EngineResource<?> loadFromActiveResources(Key key, boolean isReleaseRaceFixEnabled) {
389	    EngineResource<?> active = activeResources.get(key);
390	    if (active != null) {
391	      if (isReleaseRaceFixEnabled) {
392	        // A count of zero means another thread just dropped the last hold and is moving the
393	        // resource into the memory cache (see EngineResource#acquireIfInUse). Treat it as a miss.
394	        if (!active.acquireIfInUse()) {
395	          return null;
396	        }
397	      } else {
398	        active.acquire();
399	      }
400	    }
401	
402	    return active;
403	  }
404	
405	  private EngineResource<?> loadFromCache(Key key) {
406	    EngineResource<?> cached = getEngineResourceFromCache(key);
407	    if (cached != null) {
408	      cached.acquire();
409	      activeResources.activate(key, cached);
410	    }
411	    return cached;
412	  }
413	
414	  private EngineResource<?> getEngineResourceFromCache(Key key) {
415	    Resource<?> cached = cache.remove(key);
416	
417	    if (cached == null) {
418	      return null;
419	    }
420	    if (cached instanceof EngineResource) {
421	      // Save an object allocation if we've cached an EngineResource (the typical case).
422	      return (EngineResource<?>) cached;
423	    }
424	    return new EngineResource<>(
425	        cached,
426	        /* isMemoryCacheable= */ true,
427	        /* isRecyclable= */ true,
428	        key,
429	        /* listener= */ this);
430	  }
