432	  public void release(Resource<?> resource) {
433	    if (resource instanceof EngineResource) {
434	      ((EngineResource<?>) resource).release();
435	    } else {
436	      throw new IllegalArgumentException("Cannot release anything but an EngineResource");
437	    }
438	  }
