440	  @SuppressWarnings("unchecked")
441	  @Override
442	  public synchronized void onEngineJobComplete(
443	      EngineJob<?> engineJob, Key key, EngineResource<?> resource) {
444	    // A null resource indicates that the load failed, usually due to an exception.
445	    if (resource != null && resource.isMemoryCacheable()) {
446	      activeResources.activate(key, resource);
447	    }
448	
449	    jobs.removeIfCurrent(key, engineJob);
450	  }
