457	  @Override
458	  public void onResourceRemoved(@NonNull final Resource<?> resource) {
459	    // Avoid deadlock with RequestManagers when recycling triggers recursive clear() calls.
460	    // See b/145519760.
461	    resourceRecycler.recycle(resource, /* forceNextFrame= */ true);
462	  }
