464	  @Override
465	  public void onResourceReleased(Key cacheKey, EngineResource<?> resource) {
466	    activeResources.deactivate(cacheKey);
467	    if (resource.isMemoryCacheable()) {
468	      cache.put(cacheKey, resource);
469	    } else {
470	      resourceRecycler.recycle(resource, /* forceNextFrame= */ false);
471	    }
472	  }
