485	  /**
486	   * Allows a request to indicate it no longer is interested in a given load.
487	   *
488	   * <p>Non-final for mocking.
489	   */
490	  public class LoadStatus {
491	    private final EngineJob<?> engineJob;
492	    private final ResourceCallback cb;
493	
494	    LoadStatus(ResourceCallback cb, EngineJob<?> engineJob) {
495	      this.cb = cb;
496	      this.engineJob = engineJob;
497	    }
498	
499	    public void cancel() {
500	      // Acquire the Engine lock so that a new request can't get access to a particular EngineJob
501	      // just after the EngineJob has been cancelled. Without this lock, we'd allow new requests
502	      // to find the cancelling EngineJob in our Jobs data structure. With this lock, the EngineJob
503	      // is both cancelled and removed from Jobs atomically.
504	      synchronized (Engine.this) {
505	        engineJob.removeCallback(cb);
506	      }
507	    }
508	  }
