101	  private synchronized DiskLruCache getDiskCache() throws IOException {
102	    if (diskLruCache == null) {
103	      diskLruCache =
104	          DiskLruCache.experimentalOpen(
105	              directory, APP_VERSION, VALUE_COUNT, maxSize, memoizePathNames);
106	    }
107	    return diskLruCache;
108	  }
