110	  @Override
111	  public File get(Key key) {
112	    String safeKey = safeKeyGenerator.getSafeKey(key);
113	    if (Log.isLoggable(TAG, Log.VERBOSE)) {
114	      Log.v(TAG, "Get: Obtained: " + safeKey + " for for Key: " + key);
115	    }
116	    try {
117	      // It is possible that the there will be a put in between these two gets. If so that shouldn't
118	      // be a problem because we will always put the same value at the same key so our input streams
119	      // will still represent the same data.
120	      final DiskLruCache.Value value = getDiskCache().get(safeKey);
121	      if (value != null) {
122	        return value.getFile(0);
123	      }
124	    } catch (IOException e) {
125	      if (Log.isLoggable(TAG, Log.WARN)) {
126	        Log.w(TAG, "Unable to get from disk cache", e);
127	      }
128	    }
129	    return null;
130	  }
