132	  @Override
133	  public void put(Key key, Writer writer) {
134	    // We want to make sure that puts block so that data is available when put completes. We may
135	    // actually not write any data if we find that data is written by the time we acquire the lock.
136	    String safeKey = safeKeyGenerator.getSafeKey(key);
137	    writeLocker.acquire(safeKey);
138	    try {
139	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
140	        Log.v(TAG, "Put: Obtained: " + safeKey + " for for Key: " + key);
141	      }
142	      try {
143	        // We assume we only need to put once, so if data was written while we were trying to get
144	        // the lock, we can simply abort.
145	        DiskLruCache diskCache = getDiskCache();
146	        Value current = diskCache.get(safeKey);
147	        if (current != null) {
148	          return;
149	        }
150	
151	        DiskLruCache.Editor editor = diskCache.edit(safeKey);
152	        if (editor == null) {
153	          throw new IllegalStateException("Had two simultaneous puts for: " + safeKey);
154	        }
155	        try {
156	          File file = editor.getFile(0);
157	          if (writer.write(file)) {
158	            editor.commit();
159	          }
160	        } finally {
161	          editor.abortUnlessCommitted();
162	        }
163	      } catch (IOException e) {
164	        if (Log.isLoggable(TAG, Log.WARN)) {
165	          Log.w(TAG, "Unable to put to disk cache", e);
166	        }
167	      }
168	    } finally {
169	      writeLocker.release(safeKey);
170	    }
