176	    try {
177	      getDiskCache().remove(safeKey);
178	    } catch (IOException e) {
179	      if (Log.isLoggable(TAG, Log.WARN)) {
180	        Log.w(TAG, "Unable to delete from disk cache", e);
181	      }
182	    }
183	  }
184	
185	  @Override
186	  public synchronized void clear() {
187	    try {
