2	
3	import androidx.annotation.Nullable;
4	import com.bumptech.glide.util.Synthetic;
5	import java.util.ArrayList;
6	import java.util.HashMap;
7	import java.util.List;
8	import java.util.Map;
9	
10	/**
11	 * Similar to {@link java.util.LinkedHashMap} when access ordered except that it is access ordered
12	 * on groups of bitmaps rather than individual objects. The idea is to be able to find the LRU
13	 * bitmap size, rather than the LRU bitmap object. We can then remove bitmaps from the least
14	 * recently used size of bitmap when we need to reduce our cache size.
15	 *
16	 * <p>For the purposes of the LRU, we count gets for a particular size of bitmap as an access, even
17	 * if no bitmaps of that size are present. We do not count addition or removal of bitmaps as an
18	 * access.
19	 */
20	class GroupedLinkedMap<K extends Poolable, V> {
21	  private final LinkedEntry<K, V> head = new LinkedEntry<>();
22	  private final Map<K, LinkedEntry<K, V>> keyToEntry = new HashMap<>();
23	
24	  public void put(K key, V value) {
25	    LinkedEntry<K, V> entry = keyToEntry.get(key);
26	
27	    if (entry == null) {
28	      entry = new LinkedEntry<>(key);
29	      makeTail(entry);
30	      keyToEntry.put(key, entry);
31	    } else {
32	      key.offer();
33	    }
34	
35	    entry.add(value);
36	  }
37	
38	  @Nullable
39	  public V get(K key) {
40	    LinkedEntry<K, V> entry = keyToEntry.get(key);
41	    if (entry == null) {
42	      entry = new LinkedEntry<>(key);
43	      keyToEntry.put(key, entry);
44	    } else {
45	      key.offer();
46	    }
47	
48	    makeHead(entry);
49	
50	    return entry.removeLast();
51	  }
52	
53	  @Nullable
54	  public V removeLast() {
55	    LinkedEntry<K, V> last = head.prev;
56	
57	    while (!last.equals(head)) {
58	      V removed = last.removeLast();
59	      if (removed != null) {
60	        return removed;
61	      }
62	      // We will clean up empty lru entries since they are likely to have been one off or
63	      // unusual sizes and
64	      // are not likely to be requested again so the gc thrash should be minimal. Doing so will
65	      // speed up our
66	      // removeLast operation in the future and prevent our linked list from growing to
67	      // arbitrarily large
68	      // sizes.
69	      removeEntry(last);
70	      keyToEntry.remove(last.key);
71	      last.key.offer();
72	
73	      last = last.prev;
74	    }
75	
76	    return null;
77	  }
78	
79	  @Override
80	  public String toString() {
81	    StringBuilder sb = new StringBuilder("GroupedLinkedMap( ");
82	    LinkedEntry<K, V> current = head.next;
83	    boolean hadAtLeastOneItem = false;
84	    while (!current.equals(head)) {
85	      hadAtLeastOneItem = true;
86	      sb.append('{').append(current.key).append(':').append(current.size()).append("}, ");
87	      current = current.next;
88	    }
89	    if (hadAtLeastOneItem) {
90	      sb.delete(sb.length() - 2, sb.length());
91	    }
92	    return sb.append(" )").toString();
93	  }
94	
95	  // Make the entry the most recently used item.
96	  private void makeHead(LinkedEntry<K, V> entry) {
97	    removeEntry(entry);
98	    entry.prev = head;
99	    entry.next = head.next;
100	    updateEntry(entry);
101	  }
102	
103	  // Make the entry the least recently used item.
104	  private void makeTail(LinkedEntry<K, V> entry) {
105	    removeEntry(entry);
106	    entry.prev = head.prev;
107	    entry.next = head;
108	    updateEntry(entry);
109	  }
110	
111	  private static <K, V> void updateEntry(LinkedEntry<K, V> entry) {
112	    entry.next.prev = entry;
113	    entry.prev.next = entry;
114	  }
115	
116	  private static <K, V> void removeEntry(LinkedEntry<K, V> entry) {
117	    entry.prev.next = entry.next;
118	    entry.next.prev = entry.prev;
119	  }
120	
121	  private static class LinkedEntry<K, V> {
122	    @Synthetic final K key;
123	    private List<V> values;
124	    LinkedEntry<K, V> next;
125	    LinkedEntry<K, V> prev;
126	
127	    // Used only for the first item in the list which we will treat specially and which will not
128	    // contain a value.
129	    LinkedEntry() {
130	      this(null);
131	    }
132	
133	    LinkedEntry(K key) {
134	      next = prev = this;
135	      this.key = key;
136	    }
137	
138	    @Nullable
139	    public V removeLast() {
140	      final int valueSize = size();
141	      return valueSize > 0 ? values.remove(valueSize - 1) : null;
142	    }
143	
144	    public int size() {
145	      return values != null ? values.size() : 0;
146	    }
147	
148	    public void add(V value) {
149	      if (values == null) {
150	        values = new ArrayList<>();
151	      }
152	      values.add(value);
153	    }
154	  }
155	}
