2	
3	import android.util.Log;
4	import androidx.annotation.Nullable;
5	import androidx.annotation.VisibleForTesting;
6	import com.bumptech.glide.util.Preconditions;
7	import com.bumptech.glide.util.Synthetic;
8	import java.util.HashMap;
9	import java.util.Map;
10	import java.util.NavigableMap;
11	import java.util.TreeMap;
12	
13	/**
14	 * A fixed size Array Pool that evicts arrays using an LRU strategy to keep the pool under the
15	 * maximum byte size.
16	 */
17	public final class LruArrayPool implements ArrayPool {
18	  // 4MB.
19	  private static final int DEFAULT_SIZE = 4 * 1024 * 1024;
20	
21	  /**
22	   * The maximum number of times larger an int array may be to be than a requested size to eligible
23	   * to be returned from the pool.
24	   */
25	  @VisibleForTesting static final int MAX_OVER_SIZE_MULTIPLE = 8;
26	
27	  /** Used to calculate the maximum % of the total pool size a single byte array may consume. */
28	  private static final int SINGLE_ARRAY_MAX_SIZE_DIVISOR = 2;
29	
30	  private final GroupedLinkedMap<Key, Object> groupedMap = new GroupedLinkedMap<>();
31	  private final KeyPool keyPool = new KeyPool();
32	  private final Map<Class<?>, NavigableMap<Integer, Integer>> sortedSizes = new HashMap<>();
33	  private final Map<Class<?>, ArrayAdapterInterface<?>> adapters = new HashMap<>();
34	  private final int maxSize;
35	  private int currentSize;
36	
37	  @VisibleForTesting
38	  public LruArrayPool() {
39	    maxSize = DEFAULT_SIZE;
40	  }
41	
42	  /**
43	   * Constructor for a new pool.
44	   *
45	   * @param maxSize The maximum size in integers of the pool.
46	   */
47	  public LruArrayPool(int maxSize) {
48	    this.maxSize = maxSize;
49	  }
50	
51	  @Deprecated
52	  @Override
53	  public <T> void put(T array, Class<T> arrayClass) {
54	    put(array);
55	  }
56	
57	  @Override
58	  public synchronized <T> void put(T array) {
59	    @SuppressWarnings("unchecked")
60	    Class<T> arrayClass = (Class<T>) array.getClass();
61	
62	    ArrayAdapterInterface<T> arrayAdapter = getAdapterFromType(arrayClass);
63	    int size = arrayAdapter.getArrayLength(array);
64	    int arrayBytes = size * arrayAdapter.getElementSizeInBytes();
65	    if (!isSmallEnoughForReuse(arrayBytes)) {
66	      return;
67	    }
68	    Key key = keyPool.get(size, arrayClass);
69	
70	    groupedMap.put(key, array);
71	    NavigableMap<Integer, Integer> sizes = getSizesForAdapter(arrayClass);
72	    Integer current = sizes.get(key.size);
73	    sizes.put(key.size, current == null ? 1 : current + 1);
74	    currentSize += arrayBytes;
75	    evict();
76	  }
77	
78	  @Override
79	  public synchronized <T> T getExact(int size, Class<T> arrayClass) {
80	    Key key = keyPool.get(size, arrayClass);
81	    return getForKey(key, arrayClass);
82	  }
83	
84	  @Override
85	  public synchronized <T> T get(int size, Class<T> arrayClass) {
86	    Integer possibleSize = getSizesForAdapter(arrayClass).ceilingKey(size);
87	    Key key = mayFillRequest(size, possibleSize)
88	        ? keyPool.get(possibleSize, arrayClass)
89	        : keyPool.get(size, arrayClass);
90	    return getForKey(key, arrayClass);
91	  }
92	
93	  private <T> T getForKey(Key key, Class<T> arrayClass) {
94	    ArrayAdapterInterface<T> arrayAdapter = getAdapterFromType(arrayClass);
95	    T result = getArrayForKey(key);
96	    if (result != null) {
97	      currentSize -= arrayAdapter.getArrayLength(result) * arrayAdapter.getElementSizeInBytes();
98	      decrementArrayOfSize(arrayAdapter.getArrayLength(result), arrayClass);
99	    }
100	
101	    if (result == null) {
102	      if (Log.isLoggable(arrayAdapter.getTag(), Log.VERBOSE)) {
103	        Log.v(arrayAdapter.getTag(), "Allocated " + key.size + " bytes");
104	      }
105	      result = arrayAdapter.newArray(key.size);
106	    }
107	    return result;
108	  }
109	
110	  // Our cast is safe because the Key is based on the type.
111	  @SuppressWarnings({"unchecked", "TypeParameterUnusedInFormals"})
112	  @Nullable
113	  private <T> T getArrayForKey(Key key) {
114	    return (T) groupedMap.get(key);
115	  }
116	
117	  private boolean isSmallEnoughForReuse(int byteSize) {
118	    return byteSize <= maxSize / SINGLE_ARRAY_MAX_SIZE_DIVISOR;
119	  }
120	
121	  private boolean mayFillRequest(int requestedSize, Integer actualSize) {
122	    return actualSize != null
123	        && (isNoMoreThanHalfFull() || actualSize <= (MAX_OVER_SIZE_MULTIPLE * requestedSize));
124	  }
125	
126	  private boolean isNoMoreThanHalfFull() {
127	    return currentSize == 0 || maxSize / currentSize >= 2;
128	  }
129	
130	  @Override
131	  public synchronized void clearMemory() {
132	    evictToSize(0);
133	  }
134	
135	  @Override
136	  public synchronized void trimMemory(int level) {
137	    if (level >= android.content.ComponentCallbacks2.TRIM_MEMORY_BACKGROUND) {
138	      clearMemory();
139	    } else if (level >= android.content.ComponentCallbacks2.TRIM_MEMORY_UI_HIDDEN
140	        || level == android.content.ComponentCallbacks2.TRIM_MEMORY_RUNNING_CRITICAL) {
141	      evictToSize(maxSize / 2);
142	    }
143	  }
144	
145	  private void evict() {
146	    evictToSize(maxSize);
147	  }
148	
149	  private void evictToSize(int size) {
150	    while (currentSize > size) {
151	      Object evicted = groupedMap.removeLast();
152	      Preconditions.checkNotNull(evicted);
153	      ArrayAdapterInterface<Object> arrayAdapter = getAdapterFromObject(evicted);
154	      currentSize -= arrayAdapter.getArrayLength(evicted) * arrayAdapter.getElementSizeInBytes();
155	      decrementArrayOfSize(arrayAdapter.getArrayLength(evicted), evicted.getClass());
156	      if (Log.isLoggable(arrayAdapter.getTag(), Log.VERBOSE)) {
157	        Log.v(arrayAdapter.getTag(), "evicted: " + arrayAdapter.getArrayLength(evicted));
158	      }
159	    }
160	  }
161	
162	  private void decrementArrayOfSize(int size, Class<?> arrayClass) {
163	    NavigableMap<Integer, Integer> sizes = getSizesForAdapter(arrayClass);
164	    Integer current = sizes.get(size);
165	    if (current == null) {
166	      throw new NullPointerException(
167	          "Tried to decrement empty size" + ", size: " + size + ", this: " + this);
168	    }
169	    if (current == 1) {
170	      sizes.remove(size);
171	    } else {
172	      sizes.put(size, current - 1);
173	    }
174	  }
175	
176	  private NavigableMap<Integer, Integer> getSizesForAdapter(Class<?> arrayClass) {
177	    NavigableMap<Integer, Integer> sizes = sortedSizes.get(arrayClass);
178	    if (sizes == null) {
179	      sizes = new TreeMap<>();
180	      sortedSizes.put(arrayClass, sizes);
181	    }
182	    return sizes;
183	  }
184	
185	  @SuppressWarnings("unchecked")
186	  private <T> ArrayAdapterInterface<T> getAdapterFromObject(T object) {
187	    return (ArrayAdapterInterface<T>) getAdapterFromType(object.getClass());
188	  }
189	
190	  @SuppressWarnings("unchecked")
191	  private <T> ArrayAdapterInterface<T> getAdapterFromType(Class<T> arrayPoolClass) {
192	    ArrayAdapterInterface<?> adapter = adapters.get(arrayPoolClass);
193	    if (adapter != null) {
194	      return (ArrayAdapterInterface<T>) adapter;
195	    }
196	    if (arrayPoolClass.equals(int[].class)) {
197	      adapter = new IntegerArrayAdapter();
198	    } else if (arrayPoolClass.equals(byte[].class)) {
199	      adapter = new ByteArrayAdapter();
200	    } else {
201	      throw new IllegalArgumentException(
202	          "No array pool found for: " + arrayPoolClass.getSimpleName());
203	    }
204	    adapters.put(arrayPoolClass, adapter);
205	    return (ArrayAdapterInterface<T>) adapter;
206	  }
207	
208	  // VisibleForTesting
209	  int getCurrentSize() {
210	    int currentSize = 0;
211	    for (Class<?> type : sortedSizes.keySet()) {
212	      for (Integer size : sortedSizes.get(type).keySet()) {
213	        ArrayAdapterInterface<?> adapter = getAdapterFromType(type);
214	        currentSize += size * sortedSizes.get(type).get(size) * adapter.getElementSizeInBytes();
215	      }
216	    }
217	    return currentSize;
218	  }
219	
220	  private static final class KeyPool extends BaseKeyPool<Key> {
221	
222	    @Synthetic
223	    KeyPool() {}
224	
225	    Key get(int size, Class<?> arrayClass) {
