308	  private Resource<Bitmap> decode(
309	      ImageReader imageReader,
310	      int requestedWidth,
311	      int requestedHeight,
312	      Options options,
313	      DecodeCallbacks callbacks)
314	      throws IOException {
315	    byte[] bytesForOptions = byteArrayPool.get(ArrayPool.STANDARD_BUFFER_SIZE_BYTES, byte[].class);
316	    BitmapFactory.Options bitmapFactoryOptions = getDefaultOptions();
317	    bitmapFactoryOptions.inTempStorage = bytesForOptions;
318	
319	    DecodeFormat decodeFormat = options.get(DECODE_FORMAT);
320	    PreferredColorSpace preferredColorSpace = options.get(PREFERRED_COLOR_SPACE);
321	    DownsampleStrategy downsampleStrategy = options.get(DownsampleStrategy.OPTION);
322	    boolean fixBitmapToRequestedDimensions = options.get(FIX_BITMAP_SIZE_TO_REQUESTED_DIMENSIONS);
323	    boolean isHardwareConfigAllowed = Boolean.TRUE.equals(options.get(ALLOW_HARDWARE_CONFIG));
324	
325	    try {
326	      Bitmap result =
327	          decodeFromWrappedStreams(
328	              imageReader,
329	              bitmapFactoryOptions,
330	              downsampleStrategy,
331	              decodeFormat,
332	              preferredColorSpace,
333	              isHardwareConfigAllowed,
334	              requestedWidth,
335	              requestedHeight,
336	              fixBitmapToRequestedDimensions,
337	              callbacks);
338	      return BitmapResource.obtain(result, bitmapPool);
339	    } finally {
340	      releaseOptions(bitmapFactoryOptions);
341	      byteArrayPool.put(bytesForOptions);
342	    }
343	  }
344	
345	  private Bitmap decodeFromWrappedStreams(
346	      ImageReader imageReader,
347	      BitmapFactory.Options options,
348	      DownsampleStrategy downsampleStrategy,
349	      DecodeFormat decodeFormat,
350	      PreferredColorSpace preferredColorSpace,
351	      boolean isHardwareConfigAllowed,
352	      int requestedWidth,
353	      int requestedHeight,
354	      boolean fixBitmapToRequestedDimensions,
355	      DecodeCallbacks callbacks)
356	      throws IOException {
357	    long startTime = LogTime.getLogTime();
358	
359	    int[] sourceDimensions = getDimensions(imageReader, options, callbacks, bitmapPool);
360	    int sourceWidth = sourceDimensions[0];
361	    int sourceHeight = sourceDimensions[1];
362	    String sourceMimeType = options.outMimeType;
363	
364	    // If we failed to obtain the image dimensions, we may end up with an incorrectly sized Bitmap,
365	    // so we want to use a mutable Bitmap type. One way this can happen is if the image header is so
366	    // large (10mb+) that our attempt to use inJustDecodeBounds fails and we're forced to decode the
367	    // full size image.
368	    if (sourceWidth == -1 || sourceHeight == -1) {
369	      isHardwareConfigAllowed = false;
370	    }
371	
372	    int orientation = imageReader.getImageOrientation();
373	    int degreesToRotate = TransformationUtils.getExifOrientationDegrees(orientation);
374	    boolean isExifOrientationRequired = TransformationUtils.isExifOrientationRequired(orientation);
375	
376	    int targetWidth =
377	        requestedWidth == Target.SIZE_ORIGINAL
378	            ? (isRotationRequired(degreesToRotate) ? sourceHeight : sourceWidth)
379	            : requestedWidth;
380	    int targetHeight =
381	        requestedHeight == Target.SIZE_ORIGINAL
382	            ? (isRotationRequired(degreesToRotate) ? sourceWidth : sourceHeight)
383	            : requestedHeight;
384	
385	    ImageType imageType = imageReader.getImageType();
386	
387	    calculateScaling(
388	        imageType,
389	        imageReader,
390	        callbacks,
391	        bitmapPool,
392	        downsampleStrategy,
393	        degreesToRotate,
394	        sourceWidth,
395	        sourceHeight,
396	        targetWidth,
397	        targetHeight,
398	        options);
399	    calculateConfig(
400	        imageReader,
401	        decodeFormat,
402	        isHardwareConfigAllowed,
403	        isExifOrientationRequired,
404	        options,
405	        targetWidth,
406	        targetHeight);
407	
408	    boolean isKitKatOrGreater = Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT;
409	    // Prior to KitKat, the inBitmap size must exactly match the size of the bitmap we're decoding.
410	    if ((options.inSampleSize == 1 || isKitKatOrGreater) && shouldUsePool(imageType)) {
411	      int expectedWidth;
412	      int expectedHeight;
413	      if (sourceWidth >= 0
414	          && sourceHeight >= 0
415	          && fixBitmapToRequestedDimensions
416	          && isKitKatOrGreater) {
417	        expectedWidth = targetWidth;
418	        expectedHeight = targetHeight;
419	      } else {
420	        float densityMultiplier =
421	            isScaling(options) ? (float) options.inTargetDensity / options.inDensity : 1f;
422	        int sampleSize = options.inSampleSize;
423	        int downsampledWidth = (int) Math.ceil(sourceWidth / (float) sampleSize);
424	        int downsampledHeight = (int) Math.ceil(sourceHeight / (float) sampleSize);
425	        expectedWidth = Math.round(downsampledWidth * densityMultiplier);
426	        expectedHeight = Math.round(downsampledHeight * densityMultiplier);
427	
428	        if (Log.isLoggable(TAG, Log.VERBOSE)) {
429	          Log.v(
430	              TAG,
431	              "Calculated target ["
432	                  + expectedWidth
433	                  + "x"
434	                  + expectedHeight
435	                  + "] for source"
436	                  + " ["
437	                  + sourceWidth
438	                  + "x"
439	                  + sourceHeight
440	                  + "]"
441	                  + ", sampleSize: "
442	                  + sampleSize
443	                  + ", targetDensity: "
444	                  + options.inTargetDensity
445	                  + ", density: "
446	                  + options.inDensity
447	                  + ", density multiplier: "
448	                  + densityMultiplier);
449	        }
450	      }
451	      // If this isn't an image, or BitmapFactory was unable to parse the size, width and height
452	      // will be -1 here.
453	      if (expectedWidth > 0 && expectedHeight > 0) {
454	        setInBitmap(options, bitmapPool, expectedWidth, expectedHeight, experiments);
455	      }
456	    }
457	
458	    if (preferredColorSpace != null) {
459	      if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
460	        boolean isP3Eligible =
461	            preferredColorSpace == PreferredColorSpace.DISPLAY_P3
462	                && options.outColorSpace != null
463	                && options.outColorSpace.isWideGamut();
464	        options.inPreferredColorSpace =
465	            ColorSpace.get(isP3Eligible ? ColorSpace.Named.DISPLAY_P3 : ColorSpace.Named.SRGB);
466	      } else if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
467	        options.inPreferredColorSpace = ColorSpace.get(ColorSpace.Named.SRGB);
468	      }
469	    }
470	
471	    Bitmap downsampled = decodeStream(imageReader, options, callbacks, bitmapPool);
472	    callbacks.onDecodeComplete(bitmapPool, downsampled);
473	
474	    if (downsampled != null && sourceWidth > 0 && sourceHeight > 0) {
475	      if (Log.isLoggable(Engine.GLIDE_MEMORY_TRACKING_TAG, Log.DEBUG)) {
476	        logMemoryTracking(downsampleStrategy, downsampled, sourceWidth, sourceHeight);
477	      }
478	    }
479	
480	    if (Log.isLoggable(TAG, Log.VERBOSE)) {
481	      logDecode(
482	          sourceWidth,
483	          sourceHeight,
484	          sourceMimeType,
485	          options,
486	          downsampled,
487	          requestedWidth,
488	          requestedHeight,
489	          startTime);
490	    }
491	
492	    if (downsampled == null) {
493	      return null;
494	    }
495	    // If we scaled, the Bitmap density will be our inTargetDensity. Here we correct it back to
496	    // the expected density dpi.
497	    downsampled.setDensity(displayMetrics.densityDpi);
498	
499	    Bitmap rotated = TransformationUtils.rotateImageExif(bitmapPool, downsampled, orientation);
500	    if (!downsampled.equals(rotated)) {
501	      bitmapPool.put(downsampled);
502	    }
503	
504	    return rotated;
505	  }
506	
507	  private static void logMemoryTracking(
508	      DownsampleStrategy downsampleStrategy,
509	      Bitmap downsampled,
510	      int sourceWidth,
511	      int sourceHeight) {
512	    Util.logMemoryTracking(
513	        Engine.GLIDE_MEMORY_TRACKING_TAG,
514	        "Downsampler",
515	        downsampleStrategy.getClass().getSimpleName(),
516	        downsampled,
517	        sourceWidth,
518	        sourceHeight);
519	  }
