521	  private static void calculateScaling(
522	      ImageType imageType,
523	      ImageReader imageReader,
524	      DecodeCallbacks decodeCallbacks,
525	      BitmapPool bitmapPool,
526	      DownsampleStrategy downsampleStrategy,
527	      int degreesToRotate,
528	      int sourceWidth,
529	      int sourceHeight,
530	      int targetWidth,
531	      int targetHeight,
532	      BitmapFactory.Options options)
533	      throws IOException {
534	    // We can't downsample source content if we can't determine its dimensions.
535	    if (sourceWidth <= 0 || sourceHeight <= 0) {
536	      if (Log.isLoggable(TAG, Log.DEBUG)) {
537	        Log.d(
538	            TAG,
539	            "Unable to determine dimensions for: "
540	                + imageType
541	                + " with target ["
542	                + targetWidth
543	                + "x"
544	                + targetHeight
545	                + "]");
546	      }
547	      return;
548	    }
549	
550	    int orientedSourceWidth = sourceWidth;
551	    int orientedSourceHeight = sourceHeight;
552	    // If we're rotating the image +-90 degrees, we need to downsample accordingly so the image
553	    // width is decreased to near our target's height and the image height is decreased to near
554	    // our target width.
555	    //noinspection SuspiciousNameCombination
556	    if (isRotationRequired(degreesToRotate)) {
557	      orientedSourceWidth = sourceHeight;
558	      orientedSourceHeight = sourceWidth;
559	    }
560	
561	    final float exactScaleFactor =
562	        downsampleStrategy.getScaleFactor(
563	            orientedSourceWidth, orientedSourceHeight, targetWidth, targetHeight);
564	
565	    if (exactScaleFactor <= 0f) {
566	      throw new IllegalArgumentException(
567	          "Cannot scale with factor: "
568	              + exactScaleFactor
569	              + " from: "
570	              + downsampleStrategy
571	              + ", source: ["
572	              + sourceWidth
573	              + "x"
574	              + sourceHeight
575	              + "]"
576	              + ", target: ["
577	              + targetWidth
578	              + "x"
579	              + targetHeight
580	              + "]");
581	    }
582	
583	    SampleSizeRounding rounding =
584	        downsampleStrategy.getSampleSizeRounding(
585	            orientedSourceWidth, orientedSourceHeight, targetWidth, targetHeight);
586	    if (rounding == null) {
587	      throw new IllegalArgumentException("Cannot round with null rounding");
588	    }
589	
590	    int outWidth = round(exactScaleFactor * orientedSourceWidth);
591	    int outHeight = round(exactScaleFactor * orientedSourceHeight);
592	
593	    int widthScaleFactor = orientedSourceWidth / outWidth;
594	    int heightScaleFactor = orientedSourceHeight / outHeight;
595	
596	    // TODO: This isn't really right for both CenterOutside and CenterInside. Consider allowing
597	    // DownsampleStrategy to pick, or trying to do something more sophisticated like picking the
598	    // scale factor that leads to an exact match.
599	    int scaleFactor =
600	        rounding == SampleSizeRounding.MEMORY
601	            ? Math.max(widthScaleFactor, heightScaleFactor)
602	            : Math.min(widthScaleFactor, heightScaleFactor);
603	
604	    int powerOfTwoSampleSize;
605	    // BitmapFactory does not support downsampling wbmp files on platforms <= M. See b/27305903.
606	    if (Build.VERSION.SDK_INT <= 23
607	        && NO_DOWNSAMPLE_PRE_N_MIME_TYPES.contains(options.outMimeType)) {
608	      powerOfTwoSampleSize = 1;
609	    } else {
610	      powerOfTwoSampleSize = Math.max(1, Integer.highestOneBit(scaleFactor));
611	      if (rounding == SampleSizeRounding.MEMORY
612	          && powerOfTwoSampleSize < (1.f / exactScaleFactor)) {
613	        powerOfTwoSampleSize = powerOfTwoSampleSize << 1;
614	      }
615	    }
616	
617	    // Here we mimic framework logic for determining how inSampleSize division is rounded on various
618	    // versions of Android. The logic here has been tested on emulators for Android versions 15-26.
619	    // PNG - Always uses floor
620	    // JPEG - Always uses ceiling
621	    // Webp - Prior to N, always uses floor. At and after N, always uses round.
622	    options.inSampleSize = powerOfTwoSampleSize;
623	    int powerOfTwoWidth;
624	    int powerOfTwoHeight;
625	    if (imageType == ImageType.JPEG) {
626	      // libjpegturbo can downsample up to a sample size of 8. libjpegturbo uses ceiling to round.
627	      // After libjpegturbo's native rounding, skia does a secondary scale using floor
628	      // (integer division). Here we replicate that logic.
629	      int nativeScaling = Math.min(powerOfTwoSampleSize, 8);
630	      powerOfTwoWidth = (int) Math.ceil(orientedSourceWidth / (float) nativeScaling);
631	      powerOfTwoHeight = (int) Math.ceil(orientedSourceHeight / (float) nativeScaling);
632	      int secondaryScaling = powerOfTwoSampleSize / 8;
633	      if (secondaryScaling > 0) {
634	        powerOfTwoWidth = powerOfTwoWidth / secondaryScaling;
635	        powerOfTwoHeight = powerOfTwoHeight / secondaryScaling;
636	      }
637	    } else if (imageType == ImageType.PNG || imageType == ImageType.PNG_A) {
638	      powerOfTwoWidth = (int) Math.floor(orientedSourceWidth / (float) powerOfTwoSampleSize);
639	      powerOfTwoHeight = (int) Math.floor(orientedSourceHeight / (float) powerOfTwoSampleSize);
640	    } else if (imageType.isWebp()) {
641	      if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) {
642	        powerOfTwoWidth = Math.round(orientedSourceWidth / (float) powerOfTwoSampleSize);
643	        powerOfTwoHeight = Math.round(orientedSourceHeight / (float) powerOfTwoSampleSize);
644	      } else {
645	        powerOfTwoWidth = (int) Math.floor(orientedSourceWidth / (float) powerOfTwoSampleSize);
646	        powerOfTwoHeight = (int) Math.floor(orientedSourceHeight / (float) powerOfTwoSampleSize);
647	      }
648	    } else if (orientedSourceWidth % powerOfTwoSampleSize != 0
649	        || orientedSourceHeight % powerOfTwoSampleSize != 0) {
650	      // If we're not confident the image is in one of our types, fall back to checking the
651	      // dimensions again. inJustDecodeBounds decodes do obey inSampleSize.
652	      int[] dimensions = getDimensions(imageReader, options, decodeCallbacks, bitmapPool);
653	      // Power of two downsampling in BitmapFactory uses a variety of random factors to determine
654	      // rounding that we can't reliably replicate for all image formats. Use ceiling here to make
655	      // sure that we at least provide a Bitmap that's large enough to fit the content we're going
656	      // to load.
657	      powerOfTwoWidth = dimensions[0];
658	      powerOfTwoHeight = dimensions[1];
659	    } else {
660	      powerOfTwoWidth = orientedSourceWidth / powerOfTwoSampleSize;
661	      powerOfTwoHeight = orientedSourceHeight / powerOfTwoSampleSize;
662	    }
663	
664	    double adjustedScaleFactor =
665	        downsampleStrategy.getScaleFactor(
666	            powerOfTwoWidth, powerOfTwoHeight, targetWidth, targetHeight);
667	
668	    // Density scaling is only supported if inBitmap is null prior to KitKat. Avoid setting
669	    // densities here so we calculate the final Bitmap size correctly.
670	    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT) {
671	      options.inTargetDensity = adjustTargetDensityForError(adjustedScaleFactor);
672	      options.inDensity = getDensityMultiplier(adjustedScaleFactor);
673	    }
674	    if (isScaling(options)) {
675	      options.inScaled = true;
676	    } else {
677	      options.inDensity = options.inTargetDensity = 0;
678	    }
679	
680	    if (Log.isLoggable(TAG, Log.VERBOSE)) {
681	      Log.v(
682	          TAG,
683	          "Calculate scaling"
684	              + ", source: ["
685	              + sourceWidth
686	              + "x"
687	              + sourceHeight
688	              + "]"
689	              + ", degreesToRotate: "
690	              + degreesToRotate
691	              + ", target: ["
692	              + targetWidth
693	              + "x"
694	              + targetHeight
695	              + "]"
696	              + ", power of two scaled: ["
697	              + powerOfTwoWidth
698	              + "x"
699	              + powerOfTwoHeight
700	              + "]"
701	              + ", exact scale factor: "
702	              + exactScaleFactor
703	              + ", power of 2 sample size: "
704	              + powerOfTwoSampleSize
705	              + ", adjusted scale factor: "
706	              + adjustedScaleFactor
707	              + ", target density: "
708	              + options.inTargetDensity
709	              + ", density: "
710	              + options.inDensity);
711	    }
712	  }
