334	  public interface UncaughtThrowableStrategy {
335	    /** Silently catches and ignores the uncaught {@link Throwable}s. */
336	    // Public API.
337	    @SuppressWarnings("unused")
338	    UncaughtThrowableStrategy IGNORE = t -> {};
339	
340	    /** Logs the uncaught {@link Throwable}s using {@link #TAG} and {@link Log}. */
341	    UncaughtThrowableStrategy LOG =
342	        t -> {
343	          if (t != null && Log.isLoggable(TAG, Log.ERROR)) {
344	            Log.e(TAG, "Request threw uncaught throwable", t);
345	          }
346	        };
347	
348	    /** Rethrows the uncaught {@link Throwable}s to crash the app. */
349	    // Public API.
350	    @SuppressWarnings("unused")
351	    UncaughtThrowableStrategy THROW =
352	        t -> {
353	          if (t != null) {
354	            throw new RuntimeException("Request threw uncaught throwable", t);
355	          }
356	        };
357	
358	    /** The default strategy, currently {@link #LOG}. */
359	    UncaughtThrowableStrategy DEFAULT = LOG;
360	
361	    void handle(Throwable t);
362	  }
