369	        @Override
370	        public void run() {
371	          // why PMD suppression is needed: https://github.com/pmd/pmd/issues/808
372	          android.os.Process.setThreadPriority(DEFAULT_PRIORITY); // NOPMD AccessorMethodGeneration
