379	  /**
380	   * A {@link java.util.concurrent.ThreadFactory} that builds threads slightly above priority {@link
381	   * android.os.Process#THREAD_PRIORITY_BACKGROUND}.
382	   */
383	  private static final class DefaultThreadFactory implements ThreadFactory {
384	
385	    private final ThreadFactory delegate;
386	    private final String name;
387	    @Synthetic final UncaughtThrowableStrategy uncaughtThrowableStrategy;
388	    @Synthetic final boolean preventNetworkOperations;
389	    private final AtomicInteger threadNum = new AtomicInteger();
390	
391	    DefaultThreadFactory(
392	        ThreadFactory delegate,
393	        String name,
394	        UncaughtThrowableStrategy uncaughtThrowableStrategy,
395	        boolean preventNetworkOperations) {
396	      this.delegate = delegate;
397	      this.name = name;
398	      this.uncaughtThrowableStrategy = uncaughtThrowableStrategy;
399	      this.preventNetworkOperations = preventNetworkOperations;
400	    }
401	
402	    @Override
403	    public Thread newThread(@NonNull final Runnable runnable) {
404	      Thread newThread =
405	          delegate.newThread(
406	              () -> {
407	                if (preventNetworkOperations) {
408	                  StrictMode.setThreadPolicy(
409	                      new ThreadPolicy.Builder().detectNetwork().penaltyDeath().build());
410	                }
411	                try {
412	                  runnable.run();
413	                } catch (Throwable t) {
414	                  uncaughtThrowableStrategy.handle(t);
415	                }
416	              });
417	      newThread.setName("glide-" + name + "-thread-" + threadNum.getAndIncrement());
418	      return newThread;
419	    }
420	  }
