422	  /** A builder for {@link GlideExecutor}s. */
423	  public static final class Builder {
424	    /**
425	     * Prevents core and non-core threads from timing out ever if provided to {@link
426	     * #setThreadTimeoutMillis(long)}.
427	     */
428	    public static final long NO_THREAD_TIMEOUT = 0L;
429	
430	    private final boolean preventNetworkOperations;
431	    private final boolean isUnlimited;
432	
433	    private int corePoolSize;
434	    private int maximumPoolSize;
435	
436	    @NonNull private ThreadFactory threadFactory = new DefaultPriorityThreadFactory();
437	
438	    @NonNull
439	    private UncaughtThrowableStrategy uncaughtThrowableStrategy = UncaughtThrowableStrategy.DEFAULT;
440	
441	    private String name;
442	    private long threadTimeoutMillis;
443	    @Synthetic Function<? super Runnable, ? extends Runnable> onExecuteDecorator;
444	
445	    @Synthetic
446	    Builder(boolean preventNetworkOperations) {
447	      this(preventNetworkOperations, /* isUnlimited= */ false);
448	    }
449	
450	    @Synthetic
451	    Builder(boolean preventNetworkOperations, boolean isUnlimited) {
452	      this.preventNetworkOperations = preventNetworkOperations;
453	      this.isUnlimited = isUnlimited;
454	      if (isUnlimited) {
455	        corePoolSize = 0;
456	        maximumPoolSize = Integer.MAX_VALUE;
457	      }
458	    }
459	
460	    /**
461	     * Allows both core and non-core threads in the executor to be terminated if no tasks arrive for
462	     * at least the given timeout milliseconds.
463	     *
464	     * <p>Use {@link #NO_THREAD_TIMEOUT} to remove a previously set timeout.
465	     */
466	    public Builder setThreadTimeoutMillis(long threadTimeoutMillis) {
467	      this.threadTimeoutMillis = threadTimeoutMillis;
468	      return this;
469	    }
470	
471	    /** Sets the maximum number of threads to use. */
472	    public Builder setThreadCount(@IntRange(from = 1) int threadCount) {
473	      if (isUnlimited) {
474	        throw new UnsupportedOperationException(
475	            "Thread count cannot be configured on an unlimited source executor");
476	      }
477	      corePoolSize = threadCount;
478	      maximumPoolSize = threadCount;
479	      return this;
480	    }
481	
482	    /**
483	     * Sets the {@link ThreadFactory} responsible for creating threads and setting their priority.
484	     *
485	     * <p>Usage of this method may override other options on this builder. No guarantees are
486	     * provided with regards to the behavior of this method or how it interacts with other methods
487	     * on the builder. Use at your own risk.
488	     *
489	     * @deprecated This is an experimental method that may be removed without warning in a future
490	     *     version.
491	     */
492	    @Deprecated
493	    public Builder setThreadFactory(@NonNull ThreadFactory threadFactory) {
494	      this.threadFactory = threadFactory;
495	      return this;
496	    }
497	
498	    /**
499	     * Sets the {@link UncaughtThrowableStrategy} to use for unexpected exceptions thrown by tasks
500	     * on {@link GlideExecutor}s built by this {@code Builder}.
501	     */
502	    public Builder setUncaughtThrowableStrategy(@NonNull UncaughtThrowableStrategy strategy) {
503	      this.uncaughtThrowableStrategy = strategy;
504	      return this;
505	    }
506	
507	    /**
508	     * Sets the prefix to use for each thread name created by any {@link GlideExecutor}s built by
509	     * this {@code Builder}.
510	     */
511	    public Builder setName(String name) {
512	      this.name = name;
513	      return this;
514	    }
515	
516	    /**
517	     * Sets the decorator to be applied to each runnable executed by the executor.
518	     *
519	     * <p>This is an experimental method that may be removed without warning in a future version.
520	     */
521	    public Builder experimentalSetOnExecuteDecorator(
522	        Function<? super Runnable, ? extends Runnable> onExecuteDecorator) {
523	      this.onExecuteDecorator = onExecuteDecorator;
524	      return this;
525	    }
526	
527	    /** Builds a new {@link GlideExecutor} with any previously specified options. */
528	    public GlideExecutor build() {
529	      if (TextUtils.isEmpty(name)) {
530	        throw new IllegalArgumentException(
531	            "Name must be non-null and non-empty, but given: " + name);
532	      }
533	      ThreadFactory factory =
534	          new DefaultThreadFactory(
535	              threadFactory, name, uncaughtThrowableStrategy, preventNetworkOperations);
536	      BlockingQueue<Runnable> queue =
537	          isUnlimited ? new SynchronousQueue<>() : new PriorityBlockingQueue<>();
538	      ThreadPoolExecutor executor;
539	      if (onExecuteDecorator != null) {
540	        executor =
541	            new ThreadPoolExecutor(
542	                corePoolSize,
543	                maximumPoolSize,
544	                /* keepAliveTime= */ threadTimeoutMillis,
545	                TimeUnit.MILLISECONDS,
546	                queue,
547	                factory) {
548	              @Override
549	              public void execute(@NonNull Runnable command) {
550	                super.execute(onExecuteDecorator.apply(command));
551	              }
552	            };
553	      } else {
554	        executor =
555	            new ThreadPoolExecutor(
556	                corePoolSize,
557	                maximumPoolSize,
558	                /* keepAliveTime= */ threadTimeoutMillis,
559	                TimeUnit.MILLISECONDS,
560	                queue,
561	                factory);
562	      }
563	
564	      if (threadTimeoutMillis != NO_THREAD_TIMEOUT) {
565	        executor.allowCoreThreadTimeOut(true);
566	      }
567	
568	      return new GlideExecutor(executor);
569	    }
570	  }
