29	  @NonNull
30	  public static ByteBuffer fromFile(@NonNull File file) throws IOException {
31	    RandomAccessFile raf = null;
32	    FileChannel channel = null;
33	    try {
34	      long fileLength = file.length();
35	      // See #2240.
36	      if (fileLength > Integer.MAX_VALUE) {
37	        throw new IOException("File too large to map into memory");
38	      }
39	      // See b/67710449.
40	      if (fileLength == 0) {
41	        throw new IOException("File unsuitable for memory mapping");
42	      }
43	
44	      raf = new RandomAccessFile(file, "r");
45	      channel = raf.getChannel();
46	      return channel.map(FileChannel.MapMode.READ_ONLY, 0, fileLength).load();
47	    } finally {
48	      if (channel != null) {
49	        try {
50	          channel.close();
51	        } catch (IOException e) {
52	          // Ignored.
53	        }
54	      }
55	      if (raf != null) {
56	        try {
57	          raf.close();
58	        } catch (IOException e) {
59	          // Ignored.
60	        }
61	      }
62	    }
63	  }
