94	  public static void toStream(@NonNull ByteBuffer byteBuffer, @NonNull OutputStream os)
95	      throws IOException {
96	    SafeArray safeArray = getSafeArray(byteBuffer);
97	    if (safeArray != null) {
98	      os.write(safeArray.data, safeArray.offset, safeArray.offset + safeArray.limit);
99	    } else {
100	      byte[] buffer = BUFFER_REF.getAndSet(null);
101	      if (buffer == null) {
102	        buffer = new byte[BUFFER_SIZE];
103	      }
104	
105	      while (byteBuffer.remaining() > 0) {
106	        int toRead = Math.min(byteBuffer.remaining(), buffer.length);
107	        byteBuffer.get(buffer, 0 /*dstOffset*/, toRead /*byteCount*/);
108	        os.write(buffer, 0, toRead);
109	      }
110	
111	      BUFFER_REF.set(buffer);
112	    }
113	  }
