119	    SafeArray safeArray = getSafeArray(byteBuffer);
120	    if (safeArray != null && safeArray.offset == 0 && safeArray.limit == safeArray.data.length) {
121	      return byteBuffer.array();
122	    }
123	    ByteBuffer toCopy = byteBuffer.asReadOnlyBuffer();
124	    byte[] result = new byte[toCopy.limit()];
