140	  @NonNull
141	  public static ByteBuffer fromStream(@NonNull InputStream stream, boolean useHeapBuffer)
142	      throws IOException {
143	    ByteArrayOutputStream outStream = new ByteArrayOutputStream(BUFFER_SIZE);
144	
145	    byte[] buffer = BUFFER_REF.getAndSet(null);
146	    if (buffer == null) {
147	      buffer = new byte[BUFFER_SIZE];
148	    }
149	
150	    try {
151	      int n;
152	      while ((n = stream.read(buffer)) >= 0) {
153	        outStream.write(buffer, 0, n);
154	      }
155	    } finally {
