168	  /**
169	   * Creates a {@link ByteBuffer} from an {@link InputStream}, using the provided {@link ArrayPool}
170	   * to recycle intermediate reading buffers.
171	   *
172	   * @param stream The {@link InputStream} to read from.
173	   * @param useHeapBuffer True to allocate a heap {@link ByteBuffer}, false for a direct {@link
174	   *     ByteBuffer}.
175	   * @param arrayPool The {@link ArrayPool} used to pool and recycle temporary byte arrays.
176	   * @return A {@link ByteBuffer} containing the full contents of the stream.
177	   * @throws IOException If reading from the stream fails.
178	   */
179	  @NonNull
180	  public static ByteBuffer fromStream(
181	      @NonNull InputStream stream, boolean useHeapBuffer, @NonNull ArrayPool arrayPool)
182	      throws IOException {
183	    List<byte[]> buffers = new ArrayList<>();
184	    int totalSize = 0;
185	    byte[] currentBuffer = null;
186	    boolean success = false;
187	    try {
188	      while (true) {
189	        currentBuffer = arrayPool.get(BUFFER_SIZE, byte[].class);
190	        int read = 0;
191	        while (read < BUFFER_SIZE) {
192	          int count = stream.read(currentBuffer, read, BUFFER_SIZE - read);
193	          if (count == -1) {
194	            break;
195	          }
196	          read += count;
197	        }
198	        if (read == 0) {
199	          arrayPool.put(currentBuffer);
200	          currentBuffer = null;
201	          break;
202	        }
203	        buffers.add(currentBuffer);
204	        currentBuffer = null;
205	        totalSize += read;
206	        if (read < BUFFER_SIZE) {
207	          break;
208	        }
209	      }
210	
211	      ByteBuffer result =
212	          useHeapBuffer ? ByteBuffer.allocate(totalSize) : ByteBuffer.allocateDirect(totalSize);
213	
214	      int remaining = totalSize;
215	      for (byte[] b : buffers) {
216	        int toPut = Math.min(remaining, BUFFER_SIZE);
217	        result.put(b, 0, toPut);
218	        remaining -= toPut;
219	        arrayPool.put(b);
220	      }
221	      buffers.clear();
222	      success = true;
223	      return rewind(result);
224	    } finally {
225	      if (!success) {
226	        if (currentBuffer != null) {
227	          arrayPool.put(currentBuffer);
228	        }
229	        for (byte[] b : buffers) {
230	          arrayPool.put(b);
231	        }
232	      }
233	    }
234	  }
