262	  private static class ByteBufferStream extends InputStream {
263	    private static final int UNSET = -1;
264	    @NonNull private final ByteBuffer byteBuffer;
265	    private int markPos = UNSET;
266	
267	    ByteBufferStream(@NonNull ByteBuffer byteBuffer) {
268	      this.byteBuffer = byteBuffer;
269	    }
270	
271	    @Override
272	    public int available() {
273	      return byteBuffer.remaining();
274	    }
275	
276	    @Override
277	    public int read() {
278	      if (!byteBuffer.hasRemaining()) {
279	        return -1;
280	      }
281	      return byteBuffer.get() & 0xFF;
282	    }
283	
284	    @Override
285	    public synchronized void mark(int readLimit) {
286	      markPos = byteBuffer.position();
287	    }
288	
289	    @Override
290	    public boolean markSupported() {
291	      return true;
292	    }
293	
294	    @Override
295	    public int read(@NonNull byte[] buffer, int byteOffset, int byteCount) {
296	      if (!byteBuffer.hasRemaining()) {
297	        return -1;
298	      }
299	      int toRead = Math.min(byteCount, available());
300	      byteBuffer.get(buffer, byteOffset, toRead);
301	      return toRead;
302	    }
303	
304	    @Override
305	    public synchronized void reset() throws IOException {
306	      if (markPos == UNSET) {
307	        throw new IOException("Cannot reset to unset mark position");
308	      }
309	      // reset() was not implemented correctly in 4.0.4, so we track the mark position ourselves.
310	      byteBuffer.position(markPos);
311	    }
312	
313	    @Override
314	    public long skip(long byteCount) {
315	      if (!byteBuffer.hasRemaining()) {
316	        return -1;
317	      }
318	
319	      long toSkip = Math.min(byteCount, available());
320	      byteBuffer.position((int) (byteBuffer.position() + toSkip));
321	      return toSkip;
322	    }
323	  }
