100	    try {
101	      final GifHeader header = parser.parseHeader();
102	      if (header.getNumFrames() <= 0 || header.getStatus() != GifDecoder.STATUS_OK) {
103	        // If we couldn't decode the GIF, we will end up with a frame count of 0.
104	        return null;
105	      }
106	
107	      Bitmap.Config config =
108	          options.get(GifOptions.DECODE_FORMAT) == DecodeFormat.PREFER_RGB_565
109	              ? Bitmap.Config.RGB_565
110	              : Bitmap.Config.ARGB_8888;
111	
112	      int sampleSize = getSampleSize(header, width, height);
113	      GifDecoder gifDecoder = gifDecoderFactory.build(provider, header, byteBuffer, sampleSize);
114	      gifDecoder.setDefaultBitmapConfig(config);
115	      gifDecoder.advance();
116	      Bitmap firstFrame = gifDecoder.getNextFrame();
117	      if (firstFrame == null) {
118	        return null;
119	      }
120	
121	      Transformation<Bitmap> unitTransformation = UnitTransformation.get();
122	
123	      GifDrawable gifDrawable =
124	          new GifDrawable(context, gifDecoder, unitTransformation, width, height, firstFrame);
