126	      return new GifDrawableResource(gifDrawable);
127	    } finally {
128	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
129	        Log.v(TAG, "Decoded GIF from stream in " + LogTime.getElapsedMillis(startTime));
130	      }
131	    }
