109	  }
110	
111	  @NonNull
112	  @SuppressWarnings("unchecked")
113	  private static <T> Resetter<T> emptyResetter() {
114	    return (Resetter<T>) EMPTY_RESETTER;
115	  }
116	
117	  /**
118	   * Creates new instances of the given type.
119	   *
120	   * @param <T> The type of Object that will be created.
121	   */
122	  public interface Factory<T> {
123	    T create();
124	  }
125	
126	  /**
127	   * Resets state when objects are returned to the pool.
128	   *
129	   * @param <T> The type of Object that will be reset.
130	   */
131	  public interface Resetter<T> {
