122	  private Bitmap.CompressFormat getFormat(Bitmap bitmap, Options options) {
123	    Bitmap.CompressFormat format = options.get(COMPRESSION_FORMAT);
124	    if (format != null) {
125	      return format;
126	    }
127	    return bitmap.hasAlpha() ? Bitmap.CompressFormat.PNG : Bitmap.CompressFormat.JPEG;
128	  }
