102	  /**
103	   * A potentially expensive operation to crop the given Bitmap so that it fills the given
104	   * dimensions. This operation is significantly less expensive in terms of memory if a mutable
105	   * Bitmap with the given dimensions is passed in as well.
106	   *
107	   * @param pool The BitmapPool to obtain a bitmap from.
108	   * @param inBitmap The Bitmap to resize.
109	   * @param width The width in pixels of the final Bitmap.
110	   * @param height The height in pixels of the final Bitmap.
111	   * @return The resized Bitmap (will be recycled if recycled is not null).
112	   */
113	  public static Bitmap centerCrop(
114	      @NonNull BitmapPool pool, @NonNull Bitmap inBitmap, int width, int height) {
115	    if (inBitmap.getWidth() == width && inBitmap.getHeight() == height) {
116	      return inBitmap;
117	    }
118	    // From ImageView/Bitmap.createScaledBitmap.
119	    final float scale;
120	    final float dx;
121	    final float dy;
122	    Matrix m = new Matrix();
123	    if (inBitmap.getWidth() * height > width * inBitmap.getHeight()) {
124	      scale = (float) height / (float) inBitmap.getHeight();
125	      dx = (width - inBitmap.getWidth() * scale) * 0.5f;
126	      dy = 0;
127	    } else {
128	      scale = (float) width / (float) inBitmap.getWidth();
129	      dx = 0;
130	      dy = (height - inBitmap.getHeight() * scale) * 0.5f;
131	    }
132	
133	    m.setScale(scale, scale);
134	    m.postTranslate((int) (dx + 0.5f), (int) (dy + 0.5f));
135	
136	    Bitmap result = pool.get(width, height, getNonNullConfig(inBitmap));
137	    // We don't add or remove alpha, so keep the alpha setting of the Bitmap we were given.
138	    TransformationUtils.setAlpha(inBitmap, result);
139	
140	    applyMatrix(inBitmap, result, m);
141	
142	    if (result != null && !result.equals(inBitmap)) {
143	      // Log if centerCrop scaled the bitmap (either up or down).
144	      if (result.getWidth() != inBitmap.getWidth() || result.getHeight() != inBitmap.getHeight()) {
145	        if (Log.isLoggable(Engine.GLIDE_MEMORY_TRACKING_TAG, Log.DEBUG)) {
146	          Util.logMemoryTracking(
147	              Engine.GLIDE_MEMORY_TRACKING_TAG,
148	              "TransformationUtils [centerCrop]",
149	              null,
150	              result,
151	              inBitmap.getWidth(),
152	              inBitmap.getHeight());
153	        }
154	      }
155	    }
156	
157	    return result;
158	  }
