160	  /**
161	   * An expensive operation to resize the given Bitmap down so that it fits within the given
162	   * dimensions maintain the original proportions.
163	   *
164	   * @param pool The BitmapPool obtain a bitmap from.
165	   * @param inBitmap The Bitmap to shrink.
166	   * @param width The width in pixels the final image will fit within.
167	   * @param height The height in pixels the final image will fit within.
168	   * @return A new Bitmap shrunk to fit within the given dimensions, or toFit if toFit's width or
169	   *     height matches the given dimensions and toFit fits within the given dimensions
170	   */
171	  public static Bitmap fitCenter(
172	      @NonNull BitmapPool pool, @NonNull Bitmap inBitmap, int width, int height) {
173	    if (inBitmap.getWidth() == width && inBitmap.getHeight() == height) {
174	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
175	        Log.v(TAG, "requested target size matches input, returning input");
176	      }
177	      return inBitmap;
178	    }
179	    final float widthPercentage = width / (float) inBitmap.getWidth();
180	    final float heightPercentage = height / (float) inBitmap.getHeight();
181	    final float minPercentage = Math.min(widthPercentage, heightPercentage);
182	
183	    // Round here in case we've decoded exactly the image we want, but take the floor below to
184	    // avoid a line of garbage or blank pixels in images.
185	    int targetWidth = Math.round(minPercentage * inBitmap.getWidth());
186	    int targetHeight = Math.round(minPercentage * inBitmap.getHeight());
187	
188	    if (inBitmap.getWidth() == targetWidth && inBitmap.getHeight() == targetHeight) {
189	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
190	        Log.v(TAG, "adjusted target size matches input, returning input");
191	      }
192	      return inBitmap;
193	    }
194	
195	    // Take the floor of the target width/height, not round. If the matrix
196	    // passed into drawBitmap rounds differently, we want to slightly
197	    // overdraw, not underdraw, to avoid artifacts from bitmap reuse.
198	    targetWidth = (int) (minPercentage * inBitmap.getWidth());
199	    targetHeight = (int) (minPercentage * inBitmap.getHeight());
200	
201	    Bitmap.Config config = getNonNullConfig(inBitmap);
202	    Bitmap toReuse = pool.get(targetWidth, targetHeight, config);
203	
204	    // We don't add or remove alpha, so keep the alpha setting of the Bitmap we were given.
205	    TransformationUtils.setAlpha(inBitmap, toReuse);
206	
207	    if (Log.isLoggable(TAG, Log.VERBOSE)) {
208	      Log.v(TAG, "request: " + width + "x" + height);
209	      Log.v(TAG, "toFit:   " + inBitmap.getWidth() + "x" + inBitmap.getHeight());
210	      Log.v(TAG, "toReuse: " + toReuse.getWidth() + "x" + toReuse.getHeight());
211	      Log.v(TAG, "minPct:   " + minPercentage);
212	    }
213	
214	    Matrix matrix = new Matrix();
215	    matrix.setScale(minPercentage, minPercentage);
216	    applyMatrix(inBitmap, toReuse, matrix);
217	
218	    if (toReuse != null && !toReuse.equals(inBitmap)) {
219	      // Log if fitCenter scaled the bitmap (either up or down).
220	      if (toReuse.getWidth() != inBitmap.getWidth()
221	          || toReuse.getHeight() != inBitmap.getHeight()) {
222	        if (Log.isLoggable(Engine.GLIDE_MEMORY_TRACKING_TAG, Log.DEBUG)) {
223	          Util.logMemoryTracking(
224	              Engine.GLIDE_MEMORY_TRACKING_TAG,
225	              "TransformationUtils [fitCenter]",
226	              null,
227	              toReuse,
228	              inBitmap.getWidth(),
229	              inBitmap.getHeight());
230	        }
231	      }
232	    }
233	
234	    return toReuse;
235	  }
