384	  /**
385	   * Crop the image to a circle and resize to the specified width/height. The circle crop will have
386	   * the same width and height equal to the min-edge of the result image.
387	   *
388	   * @param pool The BitmapPool obtain a bitmap from.
389	   * @param inBitmap The Bitmap to resize.
390	   * @param destWidth The width in pixels of the final Bitmap.
391	   * @param destHeight The height in pixels of the final Bitmap.
392	   * @return The resized Bitmap (will be recycled if recycled is not null).
393	   */
394	  public static Bitmap circleCrop(
395	      @NonNull BitmapPool pool, @NonNull Bitmap inBitmap, int destWidth, int destHeight) {
396	    int destMinEdge = Math.min(destWidth, destHeight);
397	    float radius = destMinEdge / 2f;
398	
399	    int srcWidth = inBitmap.getWidth();
400	    int srcHeight = inBitmap.getHeight();
401	
402	    float scaleX = destMinEdge / (float) srcWidth;
403	    float scaleY = destMinEdge / (float) srcHeight;
404	    float maxScale = Math.max(scaleX, scaleY);
405	
406	    float scaledWidth = maxScale * srcWidth;
407	    float scaledHeight = maxScale * srcHeight;
408	    float left = (destMinEdge - scaledWidth) / 2f;
409	    float top = (destMinEdge - scaledHeight) / 2f;
410	
411	    RectF destRect = new RectF(left, top, left + scaledWidth, top + scaledHeight);
412	
413	    // Alpha is required for this transformation.
414	    Bitmap toTransform = getAlphaSafeBitmap(pool, inBitmap);
415	
416	    Bitmap.Config outConfig = getAlphaSafeConfig(inBitmap);
417	    Bitmap result = pool.get(destMinEdge, destMinEdge, outConfig);
418	    result.setHasAlpha(true);
419	
420	    BITMAP_DRAWABLE_LOCK.lock();
421	    try {
422	      Canvas canvas = new Canvas(result);
423	      // Draw a circle
424	      canvas.drawCircle(radius, radius, radius, CIRCLE_CROP_SHAPE_PAINT);
425	      // Draw the bitmap in the circle
426	      canvas.drawBitmap(toTransform, null, destRect, CIRCLE_CROP_BITMAP_PAINT);
427	      clear(canvas);
428	    } finally {
429	      BITMAP_DRAWABLE_LOCK.unlock();
430	    }
431	
432	    if (!toTransform.equals(inBitmap)) {
433	      pool.put(toTransform);
434	    }
435	
436	    return result;
437	  }
438	
439	  private static Bitmap getAlphaSafeBitmap(
440	      @NonNull BitmapPool pool, @NonNull Bitmap maybeAlphaSafe) {
441	    Bitmap.Config safeConfig = getAlphaSafeConfig(maybeAlphaSafe);
442	    if (safeConfig.equals(maybeAlphaSafe.getConfig())) {
443	      return maybeAlphaSafe;
444	    }
445	
446	    Bitmap argbBitmap = pool.get(maybeAlphaSafe.getWidth(), maybeAlphaSafe.getHeight(), safeConfig);
447	    new Canvas(argbBitmap).drawBitmap(maybeAlphaSafe, 0 /*left*/, 0 /*top*/, null /*paint*/);
448	
449	    // We now own this Bitmap. It's our responsibility to replace it in the pool outside this method
450	    // when we're finished with it.
451	    return argbBitmap;
452	  }
