454	  @NonNull
455	  private static Config getAlphaSafeConfig(@NonNull Bitmap inBitmap) {
456	    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
457	      // Avoid short circuiting the sdk check.
458	      if (Bitmap.Config.RGBA_F16.equals(inBitmap.getConfig())) { // NOPMD
459	        return Bitmap.Config.RGBA_F16;
460	      }
461	    }
462	
463	    return Bitmap.Config.ARGB_8888;
464	  }
