547	  private static Bitmap roundedCorners(
548	      @NonNull BitmapPool pool, @NonNull Bitmap inBitmap, DrawRoundedCornerFn drawRoundedCornerFn) {
549	
550	    // Alpha is required for this transformation.
551	    Bitmap.Config safeConfig = getAlphaSafeConfig(inBitmap);
552	    Bitmap toTransform = getAlphaSafeBitmap(pool, inBitmap);
553	    Bitmap result = pool.get(toTransform.getWidth(), toTransform.getHeight(), safeConfig);
554	
555	    result.setHasAlpha(true);
556	
557	    BitmapShader shader =
558	        new BitmapShader(toTransform, Shader.TileMode.CLAMP, Shader.TileMode.CLAMP);
559	    Paint paint = new Paint();
560	    paint.setAntiAlias(true);
561	    paint.setShader(shader);
562	    RectF rect = new RectF(0, 0, result.getWidth(), result.getHeight());
563	    BITMAP_DRAWABLE_LOCK.lock();
564	    try {
565	      Canvas canvas = new Canvas(result);
566	      canvas.drawColor(Color.TRANSPARENT, PorterDuff.Mode.CLEAR);
567	      drawRoundedCornerFn.drawRoundedCorners(canvas, paint, rect);
568	      clear(canvas);
569	    } finally {
570	      BITMAP_DRAWABLE_LOCK.unlock();
571	    }
572	
573	    if (!toTransform.equals(inBitmap)) {
574	      pool.put(toTransform);
575	    }
576	
577	    return result;
578	  }
